# Vue 3 Large File Slice Upload with Breakpoint Continuation

Here's a complete implementation of large file slice upload with breakpoint continuation in Vue 3. This solution uses the Fetch API for modern browsers and includes error handling, progress tracking, and resume capability.

## Main Component

```vue
<template>
  <div class="file-upload-container">
    <h2>Large File Upload with Breakpoint Continuation</h2>

    <div class="upload-section">
      <input 
        type="file" 
        @change="onFileSelected" 
        accept=".pdf,.mp4,.zip,.rar,.doc,.docx,.xlsx,.xls,.jpg,.jpeg,.png,.gif"
        class="file-input"
      />

      <div v-if="file" class="file-info">
        <p>Selected File: {{ file.name }} ({{ formatFileSize(file.size) }})</p>
        <p>Upload Status: {{ uploadStatus }}</p>
        <p v-if="uploadProgress > 0">Progress: {{ uploadProgress }}%</p>
      </div>

      <div v-if="file" class="upload-actions">
        <button @click="startUpload" :disabled="uploading" :class="{ disabled: uploading }">
          {{ uploading ? 'Uploading...' : 'Start Upload' }}
        </button>
        <button @click="cancelUpload" v-if="uploading" :disabled="uploading">
          Cancel
        </button>
      </div>

      <div v-if="uploading" class="progress-bar">
        <div 
          class="progress" 
          :style="{ width: uploadProgress + '%' }"
        ></div>
      </div>

      <div v-if="uploadHistory.length > 0" class="upload-history">
        <h3>Upload History</h3>
        <ul>
          <li v-for="(entry, index) in uploadHistory" :key="index">
            <strong>{{ entry.filename }}</strong> - 
            {{ entry.status }} - 
            {{ formatFileSize(entry.size) }} - 
            {{ entry.uploadedAt }}
          </li>
        </ul>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, onMounted, onUnmounted } from 'vue'

// State management
const file = ref(null)
const uploading = ref(false)
const uploadProgress = ref(0)
const uploadStatus = ref('Ready to upload')
const uploadHistory = ref([])
const uploadChunks = ref([])
const currentChunkIndex = ref(0)
const chunkSize = ref(1024 * 1024) // 1MB chunks
const uploadUrl = ref('https://your-api-endpoint.com/upload') // Replace with your actual endpoint

// File selection handler
const onFileSelected = (event) => {
  file.value = event.target.files[0]
  if (file.value) {
    uploadStatus.value = 'File selected'
    uploadProgress.value = 0
    uploadHistory.value = []
  }
}

// Start upload process
const startUpload = async () => {
  if (!file.value) {
    alert('Please select a file first')
    return
  }

  uploading.value = true
  uploadStatus.value = 'Preparing upload...'
  uploadProgress.value = 0

  try {
    await uploadFile()
  } catch (error) {
    console.error('Upload failed:', error)
    uploadStatus.value = 'Upload failed'
    alert('Upload failed: ' + error.message)
  } finally {
    uploading.value = false
  }
}

// Main upload function
const uploadFile = async () => {
  const file = ref.value
  const totalSize = file.size
  const totalChunks = Math.ceil(totalSize / chunkSize.value)

  // Check if file is already partially uploaded
  const existingUpload = await checkExistingUpload(file.name)
  if (existingUpload) {
    // Resume from where we left off
    currentChunkIndex.value = existingUpload.chunkIndex
    uploadChunks.value = existingUpload.chunks
    uploadStatus.value = `Resuming upload from chunk ${existingUpload.chunkIndex + 1} of ${totalChunks}`
  } else {
    // Start fresh
    uploadChunks.value = []
    currentChunkIndex.value = 0
    uploadStatus.value = `Starting upload: ${totalChunks} chunks total`
  }

  // Upload each chunk
  for (let i = currentChunkIndex.value; i < totalChunks; i++) {
    const start = i * chunkSize.value
    const end = Math.min(start + chunkSize.value, totalSize)
    const chunk = file.slice(start, end)

    // Create chunk metadata
    const chunkData = {
      chunkIndex: i,
      totalChunks,
      filename: file.name,
      size: totalSize,
      chunkSize: chunkSize.value,
      start: start,
      end: end,
      uploadedAt: new Date().toISOString()
    }

    // Add to upload chunks array
    uploadChunks.value.push(chunkData)

    // Upload the chunk
    try {
      const response = await uploadChunk(chunk, chunkData)

      if (response.ok) {
        // Update progress
        const progress = ((i + 1) / totalChunks) * 100
        uploadProgress.value = Math.round(progress)
        uploadStatus.value = `Uploading chunk ${i + 1} of ${totalChunks}...`

        // Save progress to local storage
        await saveUploadProgress(file.name, i, totalChunks, chunkData)

        // Log upload history
        uploadHistory.value.push({
          filename: file.name,
          status: 'Success',
          size: totalSize,
          uploadedAt: new Date().toISOString()
        })
      } else {
        throw new Error(`Chunk upload failed with status: ${response.status}`)
      }
    } catch (error) {
      console.error(`Failed to upload chunk ${i + 1}:`, error)
      uploadStatus.value = `Upload failed at chunk ${i + 1}`
      throw error
    }
  }

  // Finalize upload
  await finalizeUpload(file.name)
  uploadStatus.value = 'Upload completed successfully!'
  alert('Upload completed successfully!')
}

// Upload a single chunk
const uploadChunk = async (chunk, chunkData) => {
  const formData = new FormData()
  formData.append('file', chunk)
  formData.append('chunkIndex', chunkData.chunkIndex)
  formData.append('totalChunks', chunkData.totalChunks)
  formData.append('filename', chunkData.filename)
  formData.append('chunkSize', chunkData.chunkSize)
  formData.append('start', chunkData.start)
  formData.append('end', chunkData.end)

  const response = await fetch(uploadUrl.value, {
    method: 'POST',
    body: formData
  })

  return response
}

// Check if there's an existing upload for this file
const checkExistingUpload = async (filename) => {
  try {
    const response = await fetch(`${uploadUrl.value}/check?filename=${encodeURIComponent(filename)}`)
    const data = await response.json()

    if (response.ok && data.exists) {
      return data
    }
  } catch (error) {
    console.warn('Failed to check existing upload:', error)
  }

  return null
}

// Save upload progress to local storage
const saveUploadProgress = async (filename, chunkIndex, totalChunks, chunkData) => {
  try {
    const progress = {
      filename,
      chunkIndex,
      totalChunks,
      chunks: chunkData,
      timestamp: new Date().toISOString()
    }

    // Save to local storage
    localStorage.setItem(`upload_${filename}`, JSON.stringify(progress))

    // Also save to server if needed
    await fetch(`${uploadUrl.value}/progress`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(progress)
    })
  } catch (error) {
    console.warn('Failed to save upload progress:', error)
  }
}

// Finalize upload (call server endpoint to merge chunks)
const finalizeUpload = async (filename) => {
  try {
    const response = await fetch(`${uploadUrl.value}/finalize`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        filename,
        totalChunks: uploadChunks.value.length
      })
    })

    if (!response.ok) {
      throw new Error(`Finalize failed with status: ${response.status}`)
    }
  } catch (error) {
    console.error('Finalize upload failed:', error)
    throw error
  }
}

// Cancel upload
const cancelUpload = async () => {
  if (!file.value) return

  try {
    // Clear local storage
    localStorage.removeItem(`upload_${file.value.name}`)

    // Clear upload history
    uploadHistory.value = []

    // Clear upload state
    uploadProgress.value = 0
    uploadStatus.value = 'Upload cancelled'
    uploading.value = false
    currentChunkIndex.value = 0
    uploadChunks.value = []

    alert('Upload cancelled successfully!')
  } catch (error) {
    console.error('Failed to cancel upload:', error)
    alert('Failed to cancel upload')
  }
}

// Format file size
const formatFileSize = (bytes) => {
  if (bytes === 0) return '0 Bytes'
  const k = 1024
  const sizes = ['Bytes', 'KB', 'MB', 'GB', 'TB']
  const i = Math.floor(Math.log(bytes) / Math.log(k))
  return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i]
}

// Cleanup on component unmount
onUnmounted(() => {
  // Clear any pending uploads
  localStorage.removeItem(`upload_${file.value?.name}`)
})
</script>

