## Server-Side Implementation (Node.js/Express)

```javascript
// server.js - Backend implementation for large file upload

const express = require('express')
const multer = require('multer')
const fs = require('fs')
const path = require('path')
const cors = require('cors')
const app = express()
const PORT = process.env.PORT || 3000

// Middleware
app.use(cors())
app.use(express.json())
app.use(express.urlencoded({ extended: true }))

// Storage configuration for chunks
const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    const uploadDir = 'uploads/chunks'
    if (!fs.existsSync(uploadDir)) {
      fs.mkdirSync(uploadDir, { recursive: true })
    }
    cb(null, uploadDir)
  },
  filename: (req, file, cb) => {
    const uniqueSuffix = Date.now() + '-' + Math.round(Math.random() * 1E9)
    const filename = `${req.body.filename}-${req.body.chunkIndex}-${uniqueSuffix}${path.extname(file.originalname)}`
    cb(null, filename)
  }
})

const upload = multer({ storage })

// Routes
app.post('/upload', upload.single('file'), (req, res) => {
  const { filename, chunkIndex, totalChunks } = req.body

  // Save chunk to disk
  const chunkPath = path.join('uploads/chunks', filename)

  // Create directory if it doesn't exist
  const dir = path.dirname(chunkPath)
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true })
  }

  // Write chunk to file
  fs.writeFileSync(chunkPath, req.file.buffer)

  // Respond with success
  res.status(200).json({
    success: true,
    message: `Chunk ${chunkIndex} of ${totalChunks} saved successfully`
  })
})

app.post('/progress', (req, res) => {
  const { filename, chunkIndex, totalChunks, chunks } = req.body

  // Save progress to database or file system
  const progressData = {
    filename,
    chunkIndex,
    totalChunks,
    chunks,
    timestamp: new Date().toISOString()
  }

  // Save to file system
  const progressPath = `uploads/progress/${filename}.json`
  fs.writeFileSync(progressPath, JSON.stringify(progressData, null, 2))

  res.status(200).json({ success: true, message: 'Progress saved successfully' })
})

app.post('/finalize', (req, res) => {
  const { filename, totalChunks } = req.body

  // Check if all chunks are uploaded
  const chunkPath = `uploads/chunks/${filename}`
  const chunkFiles = fs.readdirSync('uploads/chunks')

  // Find all chunks for this file
  const chunks = chunkFiles
    .filter(file => file.startsWith(filename))
    .sort((a, b) => {
      const aIndex = parseInt(a.split('-')[1])
      const bIndex = parseInt(b.split('-')[1])
      return aIndex - bIndex
    })

  // Check if we have all chunks
  if (chunks.length !== totalChunks) {
    return res.status(400).json({
      success: false,
      message: `Missing chunks. Expected ${totalChunks}, found ${chunks.length}`
    })
  }

  // Merge chunks into final file
  const finalPath = `uploads/${filename}`
  const finalFile = fs.createWriteStream(finalPath)

  chunks.forEach((chunkFile, index) => {
    const chunkPath = `uploads/chunks/${chunkFile}`
    const chunkStream = fs.createReadStream(chunkPath)

    chunkStream.on('data', (chunk) => {
      finalFile.write(chunk)
    })

    chunkStream.on('end', () => {
      if (index === chunks.length - 1) {
        finalFile.end()
        res.status(200).json({
          success: true,
          message: `File ${filename} merged successfully`,
          finalPath: finalPath
        })
      }
    })
  })

  // Create final file if it doesn't exist
  if (!fs.existsSync(finalPath)) {
    fs.writeFileSync(finalPath, '')
  }
})

app.get('/check', (req, res) => {
  const { filename } = req.query

  // Check if there's an existing upload for this file
  const progressPath = `uploads/progress/${filename}.json`
  if (fs.existsSync(progressPath)) {
    const progressData = JSON.parse(fs.readFileSync(progressPath, 'utf-8'))
    res.status(200).json({
      exists: true,
      chunkIndex: progressData.chunkIndex,
      totalChunks: progressData.totalChunks,
      chunks: progressData.chunks
    })
  } else {
    res.status(200).json({ exists: false })
  }
})

// Serve static files
app.use('/uploads', express.static('uploads'))

// Error handling
app.use((err, req, res, next) => {
  console.error(err.stack)
  res.status(500).json({ error: 'Something went wrong!' })
})

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`)
})
