        // Simple JavaScript for interactivity
        document.addEventListener('DOMContentLoaded', function() {
            // Add smooth scrolling for anchor links
            document.querySelectorAll('a[href^="#"]').forEach(anchor => {
                anchor.addEventListener('click', function(e) {
                    e.preventDefault();
                    document.querySelector(this.getAttribute('href')).scrollIntoView({
                        behavior: 'smooth'
                    });
                });
            });

            // Add hover effects to cards
            document.querySelectorAll('.card').forEach(card => {
                card.addEventListener('mouseenter', function() {
                    this.style.transform = 'translateY(-5px)';
                });
                card.addEventListener('mouseleave', function() {
                    this.style.transform = 'translateY(0)';
                });
            });

            // Add click events for video play buttons
            document.querySelectorAll('.video-play-btn').forEach(button => {
                button.addEventListener('click', function() {
                    alert('Video would play here!');
                });
            });

            // Add message sending functionality
            document.querySelector('.messaging-section').addEventListener('click', function(e) {
                if (e.target.classList.contains('messaging-controls') && e.target.textContent === 'Compose') {
                    alert('Compose message functionality would be implemented here!');
                }
            });
        });
    </script>
