            top: 0;
            left: 0;
            width: 100%;
            padding: 5px;
            background-color: rgba(0,0,0,0.7);
            color: white;
            font-size: 0.8rem;
            text-align: center;
            opacity: 0;
            transition: opacity 0.3s;
