                    <p>Learn the fundamentals of music theory with interactive lessons, audio examples, and practice exercises.</p>
                    <button onclick="navigateTo('scales')">Start Learning Scales</button>
                </div>
            </section>

            <!-- Scales Page -->
            <section id="scales" class="page">
                <h2>Scales</h2>
                <div class="scale-container">
