## JavaScript Logic

```javascript
// script.js
// Audio files are placeholders. In a real implementation, you would need to include actual audio files.
// For demonstration, we'll create fake audio data.

// Audio player functionality
let currentAudio = null;
let audioQueue = [];
let currentAudioIndex = -1;

// Initialize audio player
function initializeAudioPlayer() {
    // Create audio elements for each type of audio
    const audioElements = {
        scales: {
            'major-c': new Audio(),
            'minor-a': new Audio(),
            'chromatic-c': new Audio()
        },
        chords: {
            'major-c': new Audio(),
            'minor-a': new Audio(),
            'dominant7-c': new Audio()
        }
    };

    // Set up audio elements with placeholder data
    for (let type in audioElements) {
        for (let id in audioElements[type]) {
            audioElements[type][id].src = `assets/${type}/${id}.mp3`;
            audioElements[type][id].preload = 'auto';
        }
    }

    // Store audio elements
    window.audioElements = audioElements;
}

// Play audio function
function playAudio(audioId) {
    if (!audioId) return;

    const audio = window.audioElements.scales[audioId];
    if (audio) {
        currentAudio = audio;
        audio.play();
        updateAudioInfo(audioId);
    } else {
        console.error(`Audio ${audioId} not found`);
    }
}

// Stop audio function
function stopAudio() {
    if (currentAudio) {
        currentAudio.pause();
        currentAudio.currentTime = 0;
        currentAudio = null;
        updateAudioInfo('No audio playing');
    }
}

// Pause audio function
function pauseAudio() {
    if (currentAudio) {
        currentAudio.pause();
        updateAudioInfo('Paused');
    }
}

// Toggle play/pause
function togglePlay() {
    if (currentAudio) {
        if (currentAudio.paused) {
            currentAudio.play();
            updateAudioInfo(currentAudio.src);
        } else {
            currentAudio.pause();
            updateAudioInfo('Paused');
        }
    } else {
        // Try to play the first available audio
        playAudio('major-c');
    }
}

// Update audio info display
function updateAudioInfo(info) {
    document.getElementById('current-audio-info').textContent = info;
}

// Play scale
function playScale(scaleType, key) {
    const audioId = `${scaleType}-${key}`;
    playAudio(audioId);

    // Update UI
    document.getElementById(`major-c`).pause();
    document.getElementById(`minor-a`).pause();
    document.getElementById(`chromatic-c`).pause();

    // Play the selected audio
    const audio = window.audioElements.scales[`${scaleType}-${key}`];
    if (audio) {
        audio.play();
    }
}

// Play chord
function playChord(chordType, key) {
    const audioId = `${chordType}-${key}`;
    playAudio(audioId);

    // Update UI
    document.getElementById(`major-c-chord`).pause();
    document.getElementById(`minor-a-chord`).pause();
    document.getElementById(`dominant7-c`).pause();

    // Play the selected audio
    const audio = window.audioElements.chords[`${chordType}-${key}`];
    if (audio) {
        audio.play();
    }
}

// Play progression
function playProgression(chord1, chord2, chord3, chord4) {
    const chords = [chord1, chord2, chord3, chord4].filter(Boolean);
    let audioPromises = [];

    for (let i = 0; i < chords.length; i++) {
        const chord = chords[i];
        const audioId = chord.includes('major') ? `${chord}-major` : chord;
        const audio = window.audioElements.chords[audioId];

        if (audio) {
            audioPromises.push(audio.play());
        }
    }

    // Play all chords sequentially
    if (audioPromises.length > 0) {
        audioPromises[0].then(() => {
            if (audioPromises.length > 1) {
                setTimeout(() => {
                    audioPromises[1].then(() => {
                        if (audioPromises.length > 2) {
                            setTimeout(() => {
                                audioPromises[2].then(() => {
                                    if (audioPromises.length > 3) {
                                        setTimeout(() => {
                                            audioPromises[3].then(() => {
                                                // All played
                                            });
                                        }, 1000);
                                    }
                                });
                            }, 1000);
                        }
                    });
                }, 1000);
            }
        });
    }
}

// Navigation
function navigateTo(pageId) {
    // Hide all pages
    const pages = document.querySelectorAll('.page');
    pages.forEach(page => page.style.display = 'none');

    // Show selected page
    const selectedPage = document.getElementById(pageId);
    if (selectedPage) {
        selectedPage.style.display = 'block';
    }
}

// Initialize the app
document.addEventListener('DOMContentLoaded', function() {
    initializeAudioPlayer();

    // Set up navigation
    const navLinks = document.querySelectorAll('.nav-links a');
    navLinks.forEach(link => {
        link.addEventListener('click', function(e) {
            e.preventDefault();
            const pageId = this.getAttribute('href').substring(1);
            navigateTo(pageId);
        });
    });

    // Set up key selection
    const keySelect = document.getElementById('key');
    keySelect.addEventListener('change', function() {
        const key = this.value;
        updateChordOptions(key);
    });

    // Update chord options based on key
    function updateChordOptions(key = 'C') {
        const chord1Select = document.getElementById('chord1');
        const chord2Select = document.getElementById('chord2');
        const chord3Select = document.getElementById('chord3');

        // Clear existing options
        chord1Select.innerHTML = '<option value="">-- Select --</option>';
        chord2Select.innerHTML = '<option value="">-- Select --</option>';
        chord3Select.innerHTML = '<option value="">-- Select --</option>';

        // Add chord options based on key
        const chords = [];
        if (key === 'C') {
            chords.push('C', 'G', 'Am', 'F', 'D', 'A', 'E', 'F#m', 'Bm', 'Dm', 'Gm', 'Cm');
        } else if (key === 'G') {
            chords.push('G', 'D', 'Em', 'C', 'A', 'E', 'B', 'F#m', 'Cm', 'Dm', 'Gm', 'Am');
        } else if (key === 'D') {
            chords.push('D', 'A', 'Bm', 'G', 'E', 'B', 'F#', 'C#m', 'Dm', 'Gm', 'Am', 'Fm');
        } else if (key === 'A') {
            chords.push('A', 'E', 'F#m', 'D', 'B', 'F#', 'C#', 'G#m', 'Am', 'Dm', 'Em', 'Cm');
        } else if (key === 'E') {
            chords.push('E', 'B', 'C#m', 'A', 'F#', 'C#', 'G#', 'D#m', 'Em', 'Am', 'Bm', 'Gm');
        } else if (key === 'F') {
            chords.push('F', 'C', 'Dm', 'Bb', 'G', 'D', 'A', 'Em', 'Fm', 'Bbm', 'Cm', 'Gm');
        }

        // Add options to chord1
        chords.forEach(chord => {
            const option = document.createElement('option');
            option.value = chord;
            option.textContent = chord;
            chord1Select.appendChild(option);
        });

        // Update chord2 options based on chord1
        chord1Select.addEventListener('change', function() {
            const chord1 = this.value;
            chord2Select.innerHTML = '<option value="">-- Select --</option>';
            chords.forEach(chord => {
                if (chord !== chord1) {
                    const option = document.createElement('option');
                    option.value = chord;
                    option.textContent = chord;
                    chord2Select.appendChild(option);
                }
            });
        });

        // Update chord3 options based on chord2
        chord2Select.addEventListener('change', function() {
            const chord2 = this.value;
            chord3Select.innerHTML = '<option value="">-- Select --</option>';
            chords.forEach(chord => {
                if (chord !== chord1Select.value && chord !== chord2) {
                    const option = document.createElement('option');
                    option.value = chord;
                    option.textContent = chord;
                    chord3Select.appendChild(option);
                }
            });
        });
    }

    // Check progression
    function checkProgression() {
        const key = document.getElementById('key').value;
        const chord1 = document.getElementById('chord1').value;
        const chord2 = document.getElementById('chord2').value;
        const chord3 = document.getElementById('chord3').value;

        if (!chord1 || !chord2) {
            document.getElementById('result').innerHTML = '<p class="incorrect">Please select both chords.</p>';
            return;
        }

        // Get chord types
        const chord1Type = getChordType(chord1);
        const chord2Type = getChordType(chord2);

        // Check if progression is valid
        let isCorrect = false;
        const keyTones = getKeyTones(key);

        // Simple progression validation
        if (chord1Type === 'major' && chord2Type === 'minor') {
            isCorrect = true;
        } else if (chord1Type === 'minor' && chord2Type === 'major') {
            isCorrect = true;
        } else if (chord1Type === 'major' && chord2Type === 'major') {
            isCorrect = true;
        } else if (chord1Type === 'minor' && chord2Type === 'minor') {
            isCorrect = true;
        } else if (chord1Type === 'major' && chord2Type === 'dominant7') {
            isCorrect = true;
        } else if (chord1Type === 'minor' && chord2Type === 'dominant7') {
            isCorrect = true;
        }

        // Add more complex validation here

        const result = isCorrect ? 'correct' : 'incorrect';
        document.getElementById('result').innerHTML = `<p class="${result}">Your progression is ${isCorrect ? 'correct' : 'incorrect'}</p>`;

        // Play the progression
        playProgression(chord1, chord2, chord3, '');
    }

    // Get chord type
    function getChordType(chord) {
        if (chord.includes('m')) return 'minor';
        if (chord.includes('7')) return 'dominant7';
        return 'major';
    }

    // Get key tones
    function getKeyTones(key) {
        const tones = {
            'C': ['C', 'D', 'E', 'F', 'G', 'A', 'B'],
            'G': ['G', 'A', 'B', 'C', 'D', 'E', 'F#'],
            'D': ['D', 'E', 'F#', 'G', 'A', 'B', 'C#'],
            'A': ['A', 'B', 'C#', 'D', 'E', 'F#', 'G#'],
            'E': ['E', 'F#', 'G#', 'A', 'B', 'C#', 'D#'],
            'F': ['F', 'G', 'A', 'Bb', 'C', 'D', 'E']
        };
        return tones[key] || ['C', 'D', 'E', 'F', 'G', 'A', 'B'];
    }

    // Initialize with default values
    updateChordOptions();

    // Initialize audio player
    initializeAudioPlayer();

    // Set default page
    navigateTo('home');
