const Menu = require('../models/Menu');
const Category = require('../models/Category');
const { upload } = require('../middleware/uploadMiddleware');

// Chef uploads a new menu item
exports.uploadMenu = async (req, res) => {
  try {
    const { title, description, category, price } = req.body;
    const image = req.file ? req.file.path : null;

    if (!title || !description || !category || !price || !image) {
      return res.status(400).json({ message: 'All fields are required' });
    }

    const newMenu = new Menu({
      title,
      description,
      image,
      category,
      price,
      chefId: req.user.id,
      status: 'pending'
    });

    await newMenu.save();

    res.status(201).json({ 
      message: 'Menu item uploaded successfully', 
      menu: newMenu 
    });
  } catch (error) {
    console.error(error);
    res.status(500).json({ message: 'Server error', error: error.message });
  }
};

// Manager reviews and approves/rejects menu items
exports.reviewMenu = async (req, res) => {
  try {
    const { menuId, action } = req.body;
    const menu = await Menu.findById(menuId);

    if (!menu) {
      return res.status(404).json({ message: 'Menu item not found' });
    }

    if (menu.chefId.toString() === req.user.id) {
      return res.status(403).json({ message: 'Chef cannot review their own menu' });
    }

    if (action === 'approve') {
      menu.status = 'approved';
    } else if (action === 'reject') {
      menu.status = 'rejected';
    } else {
      return res.status(400).json({ message: 'Invalid action' });
    }

    menu.updatedAt = Date.now();
    await menu.save();

    res.status(200).json({ 
      message: `Menu item ${action} successfully`, 
      menu 
    });
  } catch (error) {
    console.error(error);
    res.status(500).json({ message: 'Server error', error: error.message });
  }
};

// Get all pending menus for manager review
exports.getPendingMenus = async (req, res) => {
  try {
    const pendingMenus = await Menu.find({ status: 'pending' })
      .populate('chefId', 'name email')
      .sort({ createdAt: -1 });

    res.status(200).json(pendingMenus);
  } catch (error) {
    console.error(error);
    res.status(500).json({ message: 'Server error', error: error.message });
  }
};

