import React, { useState, useEffect } from 'react';
import { getPendingMenus, reviewMenu } from '../../services/api';
import { useNavigate } from 'react-router-dom';

const ManagerReviewPanel = () => {
  const [pendingMenus, setPendingMenus] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    fetchPendingMenus();
  }, []);

  const fetchPendingMenus = async () => {
    try {
      setLoading(true);
      const menus = await getPendingMenus();
      setPendingMenus(menus);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleReview = async (menuId, action) => {
    try {
      await reviewMenu({ menuId, action });
      // Refresh the list after review
      fetchPendingMenus();
    } catch (err) {
      alert('Error reviewing menu: ' + err.message);
    }
  };

  if (loading) {
    return <div className="loading">Loading pending menus...</div>;
  }

  if (error) {
    return <div className="error">Error: {error}</div>;
  }

  return (
    <div className="manager-review-panel">
      <h2>Menu Review Panel</h2>
      <p>Review and approve/reject menu items submitted by chefs</p>

      {pendingMenus.length === 0 ? (
        <div className="no-items">
          <p>No pending menu items to review</p>
        </div>
      ) : (
        <div className="menu-list">
          {pendingMenus.map(menu => (
            <div key={menu._id} className="menu-item">
              <div className="menu-info">
                <h3>{menu.title}</h3>
                <p>{menu.description}</p>
                <p>Category: {menu.category}</p>
                <p>Price: ${menu.price}</p>
                <p>Submitted by: {menu.chefId?.name || 'Unknown Chef'}</p>
                <p>Status: <span className="status-pending">Pending</span></p>
              </div>

              <div className="action-buttons">
                <button 
                  onClick={() => handleReview(menu._id, 'approve')}
                  className="btn approve"
                >
                  Approve
                </button>
                <button 
                  onClick={() => handleReview(menu._id, 'reject')}
                  className="btn reject"
                >
                  Reject
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default ManagerReviewPanel;
