      const allMenus = await getApprovedMenus();
      setMenus(allMenus);

      // Extract unique categories
      const uniqueCategories = [...new Set(allMenus.map(menu => menu.category))];
      setCategories(uniqueCategories);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleCategoryChange = async (category) => {
    setSelectedCategory(category);

    if (category) {
      try {
        const categoryMenus = await getMenusByCategory(category);
        setMenus(categoryMenus);
      } catch (err) {
        setError(err.message);
      }
    } else {
      fetchAllMenus();
    }
  };

  if (loading) {
    return <div className="loading">Loading menu items...</div>;
  }

  if (error) {
    return <div className="error">Error: {error}</div>;
  }

  return (
    <div className="customer-menu-display">
      <h1>Restaurant Menu</h1>

      <MenuCategorySelector 
        categories={categories} 
        selectedCategory={selectedCategory}
        onCategoryChange={handleCategoryChange}
      />

      {menus.length === 0 ? (
        <div className="no-items">
          <p>No menu items available</p>
        </div>
      ) : (
        <div className="menu-items">
          {menus.map(menu => (
            <div key={menu._id} className="menu-item">
              <div className="menu-image">
                <img src={menu.image} alt={menu.title} />
              </div>
              <div className="menu-details">
                <h3>{menu.title}</h3>
                <p className="menu-description">{menu.description}</p>
                <p className="menu-category">Category: {menu.category}</p>
                <p className="menu-price">Price: ${menu.price}</p>
                <p className="menu-chef">By: {menu.chefId?.name || 'Unknown Chef'}</p>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default CustomerMenuDisplay;
