```python
from flask import Flask, render_template, redirect, url_for, flash, request, jsonify
from flask_login import login_user, logout_user, login_required, current_user
from werkzeug.utils import secure_filename
import os
import uuid
from datetime import datetime
import json

from models import db, User, Group, File, UserGroup
from forms import LoginForm, RegistrationForm, GroupForm, FileUploadForm, AdminGroupForm

def create_app():
    app = Flask(__name__)
    app.config['SECRET_KEY'] = 'your-secret-key-here'
    app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///user_group_file_system.db'
    app.config['UPLOAD_FOLDER'] = 'uploads'
    app.config['ALLOWED_EXTENSIONS'] = {'txt', 'pdf', 'png', 'jpg', 'jpeg', 'gif', 'doc', 'docx', 'xls', 'xlsx', 'ppt', 'pptx', 'zip', 'rar', 'mp4', 'mp3', 'wav', 'ogg', 'mov', 'avi', 'wmv'}

    db.init_app(app)

    with app.app_context():
        db.create_all()

    return app

app = create_app()

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/login', methods=['GET', 'POST'])
def login():
    if current_user.is_authenticated:
        return redirect(url_for('dashboard'))

    form = LoginForm()
    if form.validate_on_submit():
        user = User.query.filter_by(username=form.username.data).first()
        if user and user.check_password(form.password.data):
            login_user(user)
            flash('Logged in successfully!', 'success')
            return redirect(url_for('dashboard'))
        else:
            flash('Invalid username or password', 'danger')

    return render_template('login.html', form=form)

@app.route('/register', methods=['GET', 'POST'])
def register():
    if current_user.is_authenticated:
        return redirect(url_for('dashboard'))

    form = RegistrationForm()
    if form.validate_on_submit():
        existing_user = User.query.filter_by(username=form.username.data).first()
        if existing_user:
            flash('Username already exists', 'danger')
            return redirect(url_for('register'))

        user = User(username=form.username.data, email=form.email.data, role=form.role.data)
        user.set_password(form.password.data)

        # Assign to default group or create one if needed
        default_group = Group.query.filter_by(name='Default Group').first()
        if not default_group:
            default_group = Group(name='Default Group', description='Default group for new users')
            db.session.add(default_group)
            db.session.commit()

        user.group_id = default_group.id
        db.session.add(user)
        db.session.commit()

        flash('Registration successful! Please log in.', 'success')
        return redirect(url_for('login'))

    return render_template('register.html', form=form)

@app.route('/dashboard')
@login_required
def dashboard():
    user = current_user
    group = user.group

    # Get user's files
    user_files = File.query.filter_by(uploaded_by=user.id).all()

    return render_template('dashboard.html', user=user, group=group, files=user_files)

@app.route('/groups')
@login_required
def groups():
    if not current_user.role == 'admin':
        flash('Access denied. Only administrators can view groups.', 'danger')
        return redirect(url_for('dashboard'))

    groups = Group.query.all()
    return render_template('groups.html', groups=groups)

@app.route('/groups/<int:group_id>')
@login_required
def group_detail(group_id):
    group = Group.query.get_or_404(group_id)
    files = File.query.filter_by(group_id=group_id).all()

    return render_template('files.html', group=group, files=files)

@app.route('/upload', methods=['GET', 'POST'])
@login_required
def upload_file():
    form = FileUploadForm()
    if form.validate_on_submit():
        if 'file' not in request.files:
            flash('No file selected', 'danger')
            return redirect(request.url)

        file = request.files['file']
        if file.filename == '':
            flash('No file selected', 'danger')
            return redirect(request.url)

        if file and allowed_file(file.filename):
            # Generate unique filename
            filename = secure_filename(file.filename)
            unique_filename = str(uuid.uuid4()) + '_' + filename

            # Create group folder if it doesn't exist
            group_folder = os.path.join(app.config['UPLOAD_FOLDER'], current_user.group.name)
            os.makedirs(group_folder, exist_ok=True)

            # Save file
            filepath = os.path.join(group_folder, unique_filename)
            file.save(filepath)

            # Create file record
            file_record = File(
                filename=filename,
                filepath=unique_filename,
                file_size=os.path.getsize(filepath),
                uploaded_by=current_user.id,
                group_id=current_user.group.id
            )

            db.session.add(file_record)
            db.session.commit()

            flash(f'File "{filename}" uploaded successfully!', 'success')
            return redirect(url_for('dashboard'))

    return render_template('upload.html', form=form)

@app.route('/admin/groups', methods=['GET', 'POST'])
@login_required
def admin_groups():
    if not current_user.role == 'admin':
        flash('Access denied. Only administrators can manage groups.', 'danger')
        return redirect(url_for('dashboard'))

    form = AdminGroupForm()
    if form.validate_on_submit():
        # Create new group
        group = Group(
            name=form.name.data,
            description=form.description.data
        )
        db.session.add(group)
        db.session.commit()

        flash(f'Group "{form.name.data}" created successfully!', 'success')
        return redirect(url_for('admin_groups'))

    groups = Group.query.all()
    return render_template('admin.html', form=form, groups=groups)

@app.route('/admin/users/<int:user_id>/groups', methods=['POST'])
@login_required
def assign_user_to_group(user_id):
    if not current_user.role == 'admin':
        flash('Access denied. Only administrators can assign users to groups.', 'danger')
        return redirect(url_for('dashboard'))

    user = User.query.get_or_404(user_id)
    group_id = request.form.get('group_id')

    if not group_id:
        flash('No group selected', 'danger')
        return redirect(url_for('dashboard'))

    group = Group.query.get_or_404(group_id)

    # Check if user already in this group
    existing_assignment = UserGroup.query.filter_by(user_id=user_id, group_id=group_id).first()
    if existing_assignment:
        flash(f'User "{user.username}" is already in group "{group.name}"', 'info')
        return redirect(url_for('dashboard'))

    # Create assignment
    assignment = UserGroup(user_id=user_id, group_id=group_id)
    db.session.add(assignment)
    db.session.commit()

    flash(f'User "{user.username}" assigned to group "{group.name}" successfully!', 'success')
    return redirect(url_for('dashboard'))

@app.route('/admin/users/<int:user_id>/remove_from_group/<int:group_id>', methods=['POST'])
@login_required
def remove_user_from_group(user_id, group_id):
    if not current_user.role == 'admin':
        flash('Access denied. Only administrators can remove users from groups.', 'danger')
        return redirect(url_for('dashboard'))

    # Find the assignment
    assignment = UserGroup.query.filter_by(user_id=user_id, group_id=group_id).first()
    if not assignment:
        flash(f'User "{user_id}" is not assigned to group "{group_id}"', 'info')
        return redirect(url_for('dashboard'))

    db.session.delete(assignment)
    db.session.commit()

    flash(f'User "{user.username}" removed from group "{group.name}" successfully!', 'success')
    return redirect(url_for('dashboard'))

@app.route('/logout')
@login_required
def logout():
    logout_user()
    flash('Logged out successfully!', 'info')
    return redirect(url_for('index'))

def allowed_file(filename):
    return '.' in filename and \
           filename.rsplit('.', 1)[1].lower() in app.config['ALLOWED_EXTENSIONS']

@app.errorhandler(404)
def not_found(error):
    return render_template('404.html'), 404

@app.errorhandler(500)
def internal_error(error):
    db.session.rollback()
    return render_template('500.html'), 500

if __name__ == '__main__':
    app.run(debug=True)
