    grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
    gap: 20px;
}

.file-item {
    background: #f8f9fa;
    padding: 15px;
    border-radius: 8px;
    box-shadow: 0 2px 5px rgba(0,0,0,0.1);
}

.file-item h3 {
    margin: 0 0 10px 0;
    color: #2c3e50;
}

.file-item p {
    margin: 5px 0;
    color: #6c757d;
}

.file-item a {
    display: inline-block;
    background-color: #3498db;
    color: white;
    padding: 5px 10px;
    border-radius: 4px;
    text-decoration: none;
    margin-top: 10px;
    transition: background-color 0.3s;
}

.file-item a:hover {
    background-color: #2980b9;
}

/* Admin panel */
.admin-panel {
    max-width: 800px;
    margin: 0 auto;
    padding: 20px;
    background: white;
    border-radius: 8px;
    box-shadow: 0 2px 5px rgba(0,0,0,0.1);
}

.admin-panel h2 {
    color: #2c3e50;
    margin-bottom: 20px;
}

.admin-panel .form-group {
    margin-bottom: 15px;
}

.admin-panel .form-label {
    display: block;
    margin-bottom: 5px;
    font-weight: bold;
}

.admin-panel .form-control {
    width: 100%;
    padding: 10px;
    border: 1px solid #ddd;
    border-radius: 4px;
    font-size: 16px;
}

.admin-panel .btn {
    background-color: #3498db;
    color: white;
    padding: 10px 20px;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 16px;
