# Video Subtitle Adding Tool

Below is a comprehensive Python-based web application using Flask, HTML/CSS/JavaScript, and FFmpeg for video processing. This tool allows users to upload videos, add multiple text captions with timeline markers, customize font, color, and position, add semi-transparent background boxes, and export the final video with embedded subtitles.

## Project Structure

```
video_subtitle_tool/
├── app.py
├── static/
│   ├── css/
│   │   └── style.css
│   └── js/
│       └── main.js
├── templates/
│   └── index.html
└── requirements.txt
```

## Requirements

```txt
Flask==2.3.3
ffmpeg-python==0.2.0
werkzeug==2.3.3
python-dotenv==1.0.0
```

## app.py

```python
import os
import uuid
import tempfile
import subprocess
import json
from datetime import datetime
from flask import Flask, render_template, request, redirect, url_for, send_from_directory, jsonify, flash
from werkzeug.utils import secure_filename
from flask_wtf import FlaskForm
from wtforms import FileField, SubmitField, StringField, TextAreaField, SelectField
from wtforms.validators import DataRequired
import ffmpeg

app = Flask(__name__)
app.config['SECRET_KEY'] = 'your-secret-key-here'
app.config['UPLOAD_FOLDER'] = 'uploads'
app.config['ALLOWED_EXTENSIONS'] = {'mp4', 'avi', 'mov', 'mkv', 'wmv'}
app.config['MAX_CONTENT_LENGTH'] = 16 * 1024 * 1024  # 16MB max file size

# Create upload folder if it doesn't exist
os.makedirs(app.config['UPLOAD_FOLDER'], exist_ok=True)

# Video processing settings
DEFAULT_FONT = 'Arial'
DEFAULT_FONT_SIZE = 24
DEFAULT_FONT_COLOR = '#FFFFFF'
DEFAULT_BACKGROUND_COLOR = '#000000'
DEFAULT_BACKGROUND_OPACITY = 0.7
DEFAULT_POSITION = 'bottom'

class SubtitleForm(FlaskForm):
    video_file = FileField('Upload Video', validators=[DataRequired()])
    submit = SubmitField('Process Video')

class AddSubtitleForm(FlaskForm):
    text = TextAreaField('Subtitle Text', validators=[DataRequired()])
    start_time = StringField('Start Time (HH:MM:SS)', validators=[DataRequired()])
    end_time = StringField('End Time (HH:MM:SS)', validators=[DataRequired()])
    font = StringField('Font', default=DEFAULT_FONT)
    font_size = StringField('Font Size', default=str(DEFAULT_FONT_SIZE))
    font_color = StringField('Font Color (Hex)', default=DEFAULT_FONT_COLOR)
    background_color = StringField('Background Color (Hex)', default=DEFAULT_BACKGROUND_COLOR)
    background_opacity = StringField('Background Opacity (0.0-1.0)', default=str(DEFAULT_BACKGROUND_OPACITY))
    position = SelectField('Position', choices=[
        ('top', 'Top'),
        ('middle', 'Middle'),
        ('bottom', 'Bottom')
    ], default=DEFAULT_POSITION)
    submit = SubmitField('Add Subtitle')

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in app.config['ALLOWED_EXTENSIONS']

def generate_unique_filename(filename):
    ext = filename.rsplit('.', 1)[1].lower()
    unique_filename = f"{uuid.uuid4().hex}.{ext}"
    return unique_filename

def process_video_with_subtitles(input_video_path, subtitles_data, output_video_path):
    """
    Process video with embedded subtitles using FFmpeg
    """
    try:
        # Create a temporary file for the subtitles
        temp_subtitle_file = os.path.join(tempfile.gettempdir(), f"subtitles_{uuid.uuid4().hex}.srt")

        # Write subtitles to .srt file
        with open(temp_subtitle_file, 'w', encoding='utf-8') as f:
            for i, subtitle in enumerate(subtitles_data):
                start_time = subtitle['start_time']
                end_time = subtitle['end_time']
                text = subtitle['text']
                font = subtitle['font']
                font_size = int(subtitle['font_size'])
                font_color = subtitle['font_color']
                background_color = subtitle['background_color']
                background_opacity = float(subtitle['background_opacity'])
                position = subtitle['position']

                # Convert time format to seconds for FFmpeg
                start_seconds = convert_time_to_seconds(start_time)
                end_seconds = convert_time_to_seconds(end_time)

                # Write subtitle to .srt format
                f.write(f"{i + 1}\n")
                f.write(f"{format_time(start_seconds)} --> {format_time(end_seconds)}\n")
                f.write(f"{text}\n\n")

        # Use FFmpeg to add subtitles with background boxes
        # First, create a video with subtitles using FFmpeg
        ffmpeg.input(input_video_path) \
            .output(output_video_path, 
                    vf=f"subtitles={temp_subtitle_file}:font={font}:fontsize={font_size}:textcolor={font_color}:bordercolor={background_color}:borderw=2:box=1:boxw=1:boxcolor={background_color}:boxalpha={background_opacity * 100}", 
                    c='copy') \
            .run(capture_stdout=True, capture_stderr=True)

        # Clean up temporary file
        os.remove(temp_subtitle_file)

        return True

    except Exception as e:
        print(f"Error processing video: {e}")
        return False

def convert_time_to_seconds(time_str):
    """Convert HH:MM:SS format to seconds"""
    h, m, s = map(int, time_str.split(':'))
    return h * 3600 + m * 60 + s

def format_time(seconds):
    """Convert seconds to HH:MM:SS format"""
    h = int(seconds // 3600)
    m = int((seconds % 3600) // 60)
    s = int(seconds % 60)
    return f"{h:02d}:{m:02d}:{s:02d}"

@app.route('/', methods=['GET', 'POST'])
def index():
    form = SubtitleForm()
    if form.validate_on_submit():
        file = form.video_file.data
        if file and allowed_file(file.filename):
            filename = secure_filename(file.filename)
            unique_filename = generate_unique_filename(filename)
            file_path = os.path.join(app.config['UPLOAD_FOLDER'], unique_filename)

            file.save(file_path)

            # Process the video with subtitles
            output_video_path = os.path.join(app.config['UPLOAD_FOLDER'], f"output_{unique_filename}")

            # Create a list to store subtitle data
            subtitles_data = []

            # Here we would normally process the video and add subtitles
            # For now, we'll just return a success message
            # In a real implementation, you would have a UI to add subtitles

            # Redirect to subtitle editor page
            return redirect(url_for('add_subtitles', video_path=file_path, output_path=output_video_path))

    return render_template('index.html', form=form)

@app.route('/add_subtitles', methods=['GET', 'POST'])
def add_subtitles():
    video_path = request.args.get('video_path')
    output_path = request.args.get('output_path')

    if not video_path or not output_path:
        return redirect(url_for('index'))

    form = AddSubtitleForm()
    if form.validate_on_submit():
        # Get form data
        text = form.text.data
        start_time = form.start_time.data
        end_time = form.end_time.data
        font = form.font.data
        font_size = form.font_size.data
        font_color = form.font_color.data
        background_color = form.background_color.data
        background_opacity = form.background_opacity.data
        position = form.position.data

        # Validate time format
        try:
            convert_time_to_seconds(start_time)
            convert_time_to_seconds(end_time)
        except ValueError:
            flash('Invalid time format. Please use HH:MM:SS format.', 'error')
            return render_template('add_subtitles.html', form=form, video_path=video_path, output_path=output_path)

        # Add subtitle to data
        subtitles_data = []
        if 'subtitles_data' in session:
            subtitles_data = json.loads(session['subtitles_data'])

        subtitles_data.append({
            'text': text,
            'start_time': start_time,
            'end_time': end_time,
            'font': font,
            'font_size': font_size,
            'font_color': font_color,
            'background_color': background_color,
            'background_opacity': background_opacity,
            'position': position
        })

        session['subtitles_data'] = json.dumps(subtitles_data)

        # Process video with subtitles
        if process_video_with_subtitles(video_path, subtitles_data, output_path):
            flash('Subtitles added successfully!', 'success')
        else:
            flash('Error processing video with subtitles.', 'error')

        return redirect(url_for('add_subtitles', video_path=video_path, output_path=output_path))

    return render_template('add_subtitles.html', form=form, video_path=video_path, output_path=output_path)

@app.route('/export')
def export():
    # Get the output video path from session or request
    output_video_path = request.args.get('output_path')
    if not output_video_path:
        return redirect(url_for('index'))

    # Return the output video for download
    return send_from_directory(app.config['UPLOAD_FOLDER'], os.path.basename(output_video_path), as_attachment=True)

@app.route('/uploads/<filename>')
def uploaded_file(filename):
    return send_from_directory(app.config['UPLOAD_FOLDER'], filename)

@app.route('/api/subtitles', methods=['POST'])
def api_subtitles():
    """API endpoint for adding subtitles"""
    try:
        data = request.get_json()
        if not data:
            return jsonify({'error': 'No data provided'}), 400

        # Validate required fields
        required_fields = ['text', 'start_time', 'end_time', 'font', 'font_size', 'font_color', 'background_color', 'background_opacity', 'position']
        for field in required_fields:
            if field not in data:
                return jsonify({'error': f'Missing required field: {field}'}), 400

        # Validate time format
        try:
            convert_time_to_seconds(data['start_time'])
            convert_time_to_seconds(data['end_time'])
        except ValueError:
            return jsonify({'error': 'Invalid time format. Please use HH:MM:SS format.'}), 400

        # Process the subtitle data
        subtitles_data = []
        if 'subtitles_data' in session:
            subtitles_data = json.loads(session['subtitles_data'])

        subtitles_data.append(data)
        session['subtitles_data'] = json.dumps(subtitles_data)

        return jsonify({'status': 'success', 'message': 'Subtitle added successfully'})

    except Exception as e:
        return jsonify({'error': str(e)}), 500

if __name__ == '__main__':
    app.run(debug=True)
