## app.py

```python
from flask import Flask, render_template, request, jsonify, send_file, redirect, url_for
from werkzeug.utils import secure_filename
import os
import json
import uuid
from datetime import datetime
from pydub import AudioSegment
import tempfile
import shutil

app = Flask(__name__)
app.config['SECRET_KEY'] = 'your-secret-key-here'
app.config['UPLOAD_FOLDER'] = 'uploads'
app.config['ALLOWED_EXTENSIONS'] = {'mp3', 'wav', 'm4a', 'ogg', 'flac'}

# Create upload folder if it doesn't exist
os.makedirs(app.config['UPLOAD_FOLDER'], exist_ok=True)

# Store labeled segments for each uploaded file
label_store = {}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in app.config['ALLOWED_EXTENSIONS']

def get_audio_duration(audio_path):
    """Get duration of audio file in seconds"""
    try:
        audio = AudioSegment.from_file(audio_path)
        return len(audio) / 1000.0  # Convert milliseconds to seconds
    except Exception as e:
        return 0

def format_time(seconds):
    """Convert seconds to MM:SS format"""
    minutes = int(seconds // 60)
    seconds = int(seconds % 60)
    return f"{minutes:02d}:{seconds:02d}"

def format_time_ms(seconds):
    """Convert seconds to MM:SS.mmm format"""
    minutes = int(seconds // 60)
    seconds = int(seconds % 60)
    milliseconds = int((seconds - int(seconds)) * 1000)
    return f"{minutes:02d}:{seconds:02d}.{milliseconds:03d}"

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/upload', methods=['POST'])
def upload_file():
    if 'audio_file' not in request.files:
        return jsonify({'error': 'No file uploaded'}), 400

    file = request.files['audio_file']
    if file.filename == '':
        return jsonify({'error': 'No file selected'}), 400

    if not allowed_file(file.filename):
        return jsonify({'error': 'File type not allowed'}), 400

    # Save uploaded file
    filename = secure_filename(file.filename)
    filepath = os.path.join(app.config['UPLOAD_FOLDER'], filename)
    file.save(filepath)

    # Get audio duration
    duration = get_audio_duration(filepath)

    # Generate unique ID for this audio file
    audio_id = str(uuid.uuid4())

    # Initialize label store for this audio file
    label_store[audio_id] = {
        'filename': filename,
        'filepath': filepath,
        'duration': duration,
        'labels': []
    }

    return jsonify({
        'success': True,
        'audio_id': audio_id,
        'filename': filename,
        'duration': duration,
        'total_seconds': duration
    })

@app.route('/get_labels/<audio_id>')
def get_labels(audio_id):
    if audio_id not in label_store:
        return jsonify({'error': 'Audio not found'}), 404

    return jsonify({
        'labels': label_store[audio_id]['labels'],
        'duration': label_store[audio_id]['duration']
    })

@app.route('/add_label', methods=['POST'])
def add_label():
    data = request.get_json()
    audio_id = data.get('audio_id')
    start_time = data.get('start_time')
    end_time = data.get('end_time')
    label_text = data.get('label_text', '')

    if not audio_id or not start_time or not end_time:
        return jsonify({'error': 'Missing required parameters'}), 400

    if audio_id not in label_store:
        return jsonify({'error': 'Audio not found'}), 404

    # Validate time ranges
    duration = label_store[audio_id]['duration']
    try:
        start_time = float(start_time)
        end_time = float(end_time)
    except ValueError:
        return jsonify({'error': 'Invalid time format'}), 400

    if start_time < 0 or end_time < 0 or start_time >= duration or end_time >= duration:
        return jsonify({'error': 'Time range out of bounds'}), 400

    if start_time >= end_time:
        return jsonify({'error': 'Start time must be less than end time'}), 400

    # Add label
    label = {
        'id': str(uuid.uuid4()),
        'start_time': start_time,
        'end_time': end_time,
        'label_text': label_text,
        'created_at': datetime.now().isoformat()
    }

    label_store[audio_id]['labels'].append(label)

    return jsonify({
        'success': True,
        'label': label,
        'audio_id': audio_id
    })

@app.route('/delete_label', methods=['POST'])
def delete_label():
    data = request.get_json()
    audio_id = data.get('audio_id')
    label_id = data.get('label_id')

    if not audio_id or not label_id:
        return jsonify({'error': 'Missing required parameters'}), 400

    if audio_id not in label_store:
        return jsonify({'error': 'Audio not found'}), 404

    # Find and remove label
    for i, label in enumerate(label_store[audio_id]['labels']):
        if label['id'] == label_id:
            label_store[audio_id]['labels'].pop(i)
            return jsonify({'success': True})

    return jsonify({'error': 'Label not found'}), 404

@app.route('/export/<audio_id>')
def export_labels(audio_id):
    if audio_id not in label_store:
        return jsonify({'error': 'Audio not found'}), 404

    # Create export file
    filename = f"audio_labels_{audio_id}.json"
    filepath = os.path.join(app.config['UPLOAD_FOLDER'], filename)

    # Create export data
    export_data = {
        'audio_filename': label_store[audio_id]['filename'],
        'audio_duration': label_store[audio_id]['duration'],
        'labels': label_store[audio_id]['labels'],
        'export_date': datetime.now().isoformat()
    }

    # Write to file
    with open(filepath, 'w', encoding='utf-8') as f:
        json.dump(export_data, f, indent=2, ensure_ascii=False)

    # Return file for download
    return send_file(filepath, as_attachment=True, download_name=filename)

@app.route('/clear_audio/<audio_id>')
def clear_audio(audio_id):
    if audio_id in label_store:
        del label_store[audio_id]
    return jsonify({'success': True})

@app.route('/get_audio_info/<audio_id>')
def get_audio_info(audio_id):
    if audio_id not in label_store:
        return jsonify({'error': 'Audio not found'}), 404

    return jsonify({
        'filename': label_store[audio_id]['filename'],
        'duration': label_store[audio_id]['duration'],
        'labels_count': len(label_store[audio_id]['labels'])
    })

@app.route('/get_audio_duration/<audio_id>')
def get_audio_duration(audio_id):
    if audio_id not in label_store:
        return jsonify({'error': 'Audio not found'}), 404

    return jsonify({
        'duration': label_store[audio_id]['duration']
    })

@app.route('/get_label_ranges/<audio_id>')
def get_label_ranges(audio_id):
    if audio_id not in label_store:
        return jsonify({'error': 'Audio not found'}), 404

    labels = label_store[audio_id]['labels']
    ranges = []

    for label in labels:
        ranges.append({
            'start': label['start_time'],
            'end': label['end_time'],
            'label': label['label_text']
        })

    return jsonify({'ranges': ranges})

if __name__ == '__main__':
    app.run(debug=True)
