```javascript
document.addEventListener('DOMContentLoaded', function() {
    const uploadForm = document.getElementById('uploadForm');
    const uploadStatus = document.getElementById('uploadStatus');
    const audioPlayerContainer = document.getElementById('audioPlayerContainer');
    const audioPlayerElement = document.getElementById('audioPlayerElement');
    const audioInfo = document.getElementById('audioInfo');
    const timeline = document.getElementById('timeline');
    const labelDisplay = document.getElementById('labelDisplay');
    const labelForm = document.getElementById('labelForm');
    const labelsList = document.getElementById('labelsList');
    const addLabelBtn = document.getElementById('addLabelBtn');
    const exportBtn = document.getElementById('exportBtn');
    const clearLabelsBtn = document.getElementById('clearLabelsBtn');
    const startTimeInput = document.getElementById('startTime');
    const endTimeInput = document.getElementById('endTime');
    const labelTextInput = document.getElementById('labelText');
    const saveLabelBtn = document.getElementById('saveLabelBtn');
    const cancelLabelBtn = document.getElementById('cancelLabelBtn');
    const loading = document.getElementById('loading');

    let currentAudioId = null;
    let currentAudioDuration = 0;
    let isDragging = false;
    let dragStartX = 0;
    let dragStartPercent = 0;
    let currentLabel = null;

    // Handle file upload
    uploadForm.addEventListener('submit', async function(e) {
        e.preventDefault();

        const fileInput = document.getElementById('audioFile');
        const file = fileInput.files[0];

        if (!file) {
            uploadStatus.textContent = 'Please select a file';
            uploadStatus.style.color = 'red';
            return;
        }

        uploadStatus.textContent = 'Uploading...';
        uploadStatus.style.color = 'blue';

        try {
            const formData = new FormData();
            formData.append('audio_file', file);

            const response = await fetch('/upload', {
                method: 'POST',
                body: formData
            });

            const result = await response.json();

            if (result.success) {
                currentAudioId = result.audio_id;
                currentAudioDuration = result.duration;
                audioInfo.textContent = `Audio: ${result.filename} (${formatTime(result.duration)})`;
                audioPlayerElement.src = URL.createObjectURL(file);

                // Update UI
                audioPlayerContainer.style.display = 'block';
                uploadStatus.textContent = `Uploaded: ${result.filename}`;
                uploadStatus.style.color = 'green';

                // Initialize timeline
                updateTimeline();

                // Load existing labels
                loadLabels();

                // Set up audio player
                setupAudioPlayer();
            } else {
                uploadStatus.textContent = result.error;
                uploadStatus.style.color = 'red';
            }
        } catch (error) {
            console.error('Error uploading file:', error);
            uploadStatus.textContent = 'Error uploading file';
            uploadStatus.style.color = 'red';
        }
    });

    // Set up audio player
    function setupAudioPlayer() {
        audioPlayerElement.addEventListener('timeupdate', function() {
            updateTimeline();
        });

        audioPlayerElement.addEventListener('loadedmetadata', function() {
            currentAudioDuration = this.duration;
            updateTimeline();
        });

        audioPlayerElement.addEventListener('click', function(e) {
            const rect = this.getBoundingClientRect();
            const clickX = e.clientX - rect.left;
            const percent = clickX / rect.width;
            const time = percent * currentAudioDuration;
            audioPlayerElement.currentTime = time;
        });
    }

    // Update timeline display
    function updateTimeline() {
        if (!currentAudioDuration) return;

        const timelineWidth = timeline.offsetWidth;
        const timelineHeight = timeline.offsetHeight;

        // Clear existing labels
        timeline.innerHTML = '';

        // Create timeline bar
        const timelineBar = document.createElement('div');
        timelineBar.style.position = 'absolute';
        timelineBar.style.top = '0';
        timelineBar.style.left = '0';
        timelineBar.style.width = '100%';
        timelineBar.style.height = '100%';
        timelineBar.style.backgroundColor = '#ddd';
        timelineBar.style.borderRadius = '5px';
        timelineBar.style.cursor = 'pointer';
        timeline.appendChild(timelineBar);

        // Add time markers
        const markers = document.createElement('div');
        markers.style.position = 'absolute';
        markers.style.top = '0';
        markers.style.left = '0';
        markers.style.width = '100%';
        markers.style.height = '100%';
        markers.style.display = 'flex';
        markers.style.flexDirection = 'column';
        markers.style.justifyContent = 'flex-end';
        markers.style.padding = '0 5px';
        markers.style.pointerEvents = 'none';
        timeline.appendChild(markers);

        // Add time markers
        for (let i = 0; i <= 10; i++) {
            const marker = document.createElement('div');
            marker.style.position = 'absolute';
            marker.style.top = '0';
            marker.style.left = `${(i * 10) / 100}%`;
            marker.style.width = '1px';
            marker.style.height = '100%';
            marker.style.backgroundColor = '#333';
            marker.style.opacity = '0.5';
            marker.style.zIndex = '10';
            marker.style.pointerEvents = 'none';
            markers.appendChild(marker);

            const label = document.createElement('div');
            label.style.position = 'absolute';
            label.style.top = '0';
            label.style.left = `${(i * 10) / 100}%`;
            label.style.width = '10px';
            label.style.height = '10px';
            label.style.backgroundColor = '#333';
            label.style.borderRadius = '50%';
            label.style.zIndex = '10';
            label.style.pointerEvents = 'none';
            markers.appendChild(label);
        }

        // Add label markers
        const labels = labelStore[currentAudioId]?.labels || [];
        labels.forEach(label => {
            const startPercent = label.start_time / currentAudioDuration;
            const endPercent = label.end_time / currentAudioDuration;

            // Create start marker
            const startMarker = document.createElement('div');
            startMarker.style.position = 'absolute';
            startMarker.style.top = '0';
            startMarker.style.left = `${startPercent * 100}%`;
            startMarker.style.width = '10px';
            startMarker.style.height = '10px';
            startMarker.style.backgroundColor = '#27ae60';
            startMarker.style.borderRadius = '50%';
            startMarker.style.zIndex = '10';
            startMarker.style.pointerEvents = 'none';
            timeline.appendChild(startMarker);

            // Create end marker
            const endMarker = document.createElement('div');
            endMarker.style.position = 'absolute';
            endMarker.style.top = '0';
            endMarker.style.left = `${endPercent * 100}%`;
            endMarker.style.width = '10px';
            endMarker.style.height = '10px';
            endMarker.style.backgroundColor = '#27ae60';
            endMarker.style.borderRadius = '50%';
            endMarker.style.zIndex = '10';
            endMarker.style.pointerEvents = 'none';
            timeline.appendChild(endMarker);

            // Create label line
            const labelLine = document.createElement('div');
            labelLine.style.position = 'absolute';
            labelLine.style.top = '0';
            labelLine.style.left = `${startPercent * 100}%`;
            labelLine.style.width = `${(endPercent - startPercent) * 100}%`;
            labelLine.style.height = '100%';
            labelLine.style.backgroundColor = '#27ae60';
            labelLine.style.opacity = '0.5';
            labelLine.style.zIndex = '5';
            labelLine.style.pointerEvents = 'none';
            timeline.appendChild(labelLine);
        });

        // Add hover effect
        timelineBar.addEventListener('mouseenter', function() {
            timelineBar.style.backgroundColor = '#ccc';
        });

        timelineBar.addEventListener('mouseleave', function() {
            timelineBar.style.backgroundColor = '#ddd';
        });

        timelineBar.addEventListener('mousedown', function(e) {
            isDragging = true;
            dragStartX = e.clientX;
            dragStartPercent = (e.clientX - timeline.getBoundingClientRect().left) / timeline.offsetWidth;
        });

        document.addEventListener('mousemove', function(e) {
            if (isDragging) {
                const rect = timeline.getBoundingClientRect();
                const percent = (e.clientX - rect.left) / rect.width;
                const time = percent * currentAudioDuration;
                audioPlayerElement.currentTime = time;
            }
        });

        document.addEventListener('mouseup', function() {
            isDragging = false;
        });
    }

    // Load existing labels
    function loadLabels() {
        if (!currentAudioId) return;

        fetch(`/get_labels/${currentAudioId}`)
            .then(response => response.json())
            .then(data => {
                if (data.labels && data.labels.length > 0) {
                    renderLabels(data.labels);
                }
            })
            .catch(error => {
                console.error('Error loading labels:', error);
            });
    }

    // Render labels
    function renderLabels(labels) {
        labelsList.innerHTML = '';

        labels.forEach(label => {
            const li = document.createElement('li');
            li.innerHTML = `
                <span class="label-text">${label.label_text}</span>
                <span class="time-range">${formatTime(label.start_time)} - ${formatTime(label.end_time)}</span>
                <button class="delete-btn" data-label-id="${label.id}">Delete</button>
            `;

            // Add delete functionality
            const deleteBtn = li.querySelector('.delete-btn');
            deleteBtn.addEventListener('click', function() {
                if (confirm('Are you sure you want to delete this label?')) {
                    deleteLabel(label.id);
                }
            });

            labelsList.appendChild(li);
        });
    }

    // Add new label
    addLabelBtn.addEventListener('click', function() {
        labelForm.style.display = 'block';
        startTimeInput.value = 0;
        endTimeInput.value = 0;
        labelTextInput.value = '';
        currentLabel = null;
    });

    // Save label
    saveLabelBtn.addEventListener('click', function() {
        const startTime = parseFloat(startTimeInput.value);
        const endTime = parseFloat(endTimeInput.value);
        const labelText = labelTextInput.value.trim();

        if (isNaN(startTime) || isNaN(endTime) || startTime >= endTime) {
            alert('Please enter valid start and end times (start < end)');
            return;
        }

        if (startTime < 0 || endTime < 0 || startTime > currentAudioDuration || endTime > currentAudioDuration) {
            alert('Time range out of bounds');
            return;
        }

        // Send label to server
        fetch('/add_label', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                audio_id: currentAudioId,
                start_time: startTime,
                end_time: endTime,
                label_text: labelText
            })
        })
        .then(response => response.json())
        .then(data => {
            if (data.success) {
                // Update UI
                renderLabels(data.label);
                labelForm.style.display = 'none';
                alert('Label added successfully!');
            } else {
                alert('Error adding label: ' + data.error);
            }
        })
        .catch(error => {
            console.error('Error adding label:', error);
            alert('Error adding label');
        });
    });

    // Cancel label
    cancelLabelBtn.addEventListener('click', function() {
        labelForm.style.display = 'none';
    });

    // Export labels
    exportBtn.addEventListener('click', function() {
        if (!currentAudioId) {
            alert('No audio uploaded');
            return;
        }

        fetch(`/export/${currentAudioId}`)
            .then(response => response.json())
            .then(data => {
                if (data.success) {
                    alert('Labels exported successfully!');
                } else {
                    alert('Error exporting labels');
                }
            })
            .catch(error => {
                console.error('Error exporting labels:', error);
                alert('Error exporting labels');
            });
    });

    // Clear all labels
    clearLabelsBtn.addEventListener('click', function() {
        if (confirm('Are you sure you want to clear all labels?')) {
            fetch(`/clear_audio/${currentAudioId}`, {
                method: 'POST'
            })
            .then(response => response.json())
            .then(data => {
                if (data.success) {
                    labelsList.innerHTML = '';
                    renderLabels([]);
                    alert('All labels cleared successfully!');
                } else {
                    alert('Error clearing labels');
                }
            })
            .catch(error => {
                console.error('Error clearing labels:', error);
                alert('Error clearing labels');
            });
        }
    });

    // Delete label
    function deleteLabel(labelId) {
        if (!currentAudioId) return;

        fetch('/delete_label', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                audio_id: currentAudioId,
                label_id: labelId
            })
        })
        .then(response => response.json())
        .then(data => {
            if (data.success) {
                renderLabels(data.labels);
            } else {
                alert('Error deleting label');
            }
        })
        .catch(error => {
            console.error('Error deleting label:', error);
            alert('Error deleting label');
        });
    }

    // Format time
    function formatTime(seconds) {
        const minutes = Math.floor(seconds / 60);
        const secs = Math.floor(seconds % 60);
        return `${minutes}:${secs < 10 ? '0' : ''}${secs}`;
    }

    // Initialize
    function initialize() {
        // Set up audio player controls
        audioPlayerElement.addEventListener('timeupdate', function() {
            updateTimeline();
        });

        // Set up audio player events
        audioPlayerElement.addEventListener('loadedmetadata', function() {
            currentAudioDuration = this.duration;
            updateTimeline();
        });

        // Set up timeline interaction
        timeline.addEventListener('mousedown', function(e) {
            isDragging = true;
            dragStartX = e.clientX;
            dragStartPercent = (e.clientX - timeline.getBoundingClientRect().left) / timeline.offsetWidth;
        });

        document.addEventListener('mousemove', function(e) {
            if (isDragging) {
                const rect = timeline.getBoundingClientRect();
                const percent = (e.clientX - rect.left) / rect.width;
                const time = percent * currentAudioDuration;
                audioPlayerElement.currentTime = time;
            }
        });

        document.addEventListener('mouseup', function() {
            isDragging = false;
        });
    }

    // Initialize app
    initialize();
});
