from datetime import datetime, timedelta
from typing import List, Dict, Optional
from dataclasses import dataclass
import json
import os

# Simulated database (in real app, use SQLite/PostgreSQL)
class DeviceMaintenanceDB:
    def __init__(self):
        self.devices = []
        self.maintenance_records = []

    def add_device(self, device_id: str, name: str, maintenance_cycle: str, last_maintenance: Optional[datetime] = None):
        """Register a new device with maintenance cycle"""
        device = {
            "id": device_id,
            "name": name,
            "maintenance_cycle": maintenance_cycle,  # "hours:1000" or "days:30"
            "last_maintenance": last_maintenance or datetime.now(),
            "status": self._calculate_status(device_id)
        }
        self.devices.append(device)
        return device

    def get_device(self, device_id: str) -> Optional[Dict]:
        """Get device by ID"""
        for device in self.devices:
            if device["id"] == device_id:
                return device
        return None

    def add_maintenance_record(self, device_id: str, maintainer: str, consumables: List[str], timestamp: datetime):
        """Add maintenance record"""
        record = {
            "id": len(self.maintenance_records) + 1,
            "device_id": device_id,
            "maintainer": maintainer,
            "consumables": consumables,
            "timestamp": timestamp
        }
        self.maintenance_records.append(record)
        # Update device status
        self._update_device_status(device_id)
        return record

    def get_maintenance_history(self, device_id: str) -> List[Dict]:
        """Get maintenance history for a device"""
        return [r for r in self.maintenance_records if r["device_id"] == device_id]

    def _calculate_status(self, device_id: str) -> str:
        """Calculate maintenance status based on cycle"""
        device = self.get_device(device_id)
        if not device:
            return "unknown"

        cycle_type, cycle_value = device["maintenance_cycle"].split(":", 1)
        last_maintenance = device["last_maintenance"]

        if cycle_type == "hours":
            cycle_hours = int(cycle_value)
            now = datetime.now()
            hours_since_last = (now - last_maintenance).total_seconds() / 3600
            if hours_since_last >= cycle_hours:
                return "red"  # overdue
            elif hours_since_last >= cycle_hours * 0.7:
                return "yellow"  # due within 7 days
            else:
                return "green"  # normal
        elif cycle_type == "days":
            cycle_days = int(cycle_value)
            now = datetime.now()
            days_since_last = (now - last_maintenance).days
            if days_since_last >= cycle_days:
                return "red"  # overdue
            elif days_since_last >= cycle_days * 0.7:
                return "yellow"  # due within 7 days
            else:
                return "green"  # normal
        return "unknown"

    def _update_device_status(self, device_id: str):
        """Update device status after adding maintenance record"""
        device = self.get_device(device_id)
        if device:
            device["status"] = self._calculate_status(device_id)

# Mock data for testing
def initialize_mock_data(db: DeviceMaintenanceDB):
    """Initialize sample data"""
    db.add_device("DEV001", "Server A", "hours:240")
    db.add_device("DEV002", "Printer B", "days:30")
    db.add_device("DEV003", "Router C", "hours:100")

    # Add some maintenance records
    db.add_maintenance_record("DEV001", "John Doe", ["Filter A", "Oil"], datetime.now() - timedelta(hours=250))
    db.add_maintenance_record("DEV002", "Jane Smith", ["Toner", "Paper"], datetime.now() - timedelta(days=25))
    db.add_maintenance_record("DEV003", "Bob Johnson", ["Fan", "Cable"], datetime.now() - timedelta(hours=110))

# Simple web interface using Flask
from flask import Flask, render_template, request, jsonify

app = Flask(__name__)
db = DeviceMaintenanceDB()
initialize_mock_data(db)

@app.route('/')
def index():
    """Homepage displaying devices with status colors"""
    devices = []
    for device in db.devices:
        devices.append({
            "id": device["id"],
            "name": device["name"],
            "status": device["status"],
            "last_maintenance": device["last_maintenance"].strftime("%Y-%m-%d %H:%M")
        })
    return render_template('index.html', devices=devices)

@app.route('/device/<device_id>')
def device_detail(device_id):
    """Display maintenance history and form for adding new record"""
    device = db.get_device(device_id)
    if not device:
        return "Device not found", 404

    history = db.get_maintenance_history(device_id)
    return render_template('device_detail.html', device=device, history=history)

@app.route('/add_maintenance', methods=['POST'])
def add_maintenance():
    """Add new maintenance record"""
    data = request.get_json()
    device_id = data.get("device_id")
    maintainer = data.get("maintainer")
    consumables = data.get("consumables", [])
    timestamp = datetime.now()

    record = db.add_maintenance_record(device_id, maintainer, consumables, timestamp)
    return jsonify({"success": True, "record": record})

if __name__ == '__main__':
    app.run(debug=True)
