    createControl(name, label, type, options, config = {}) {
        const controlGroup = document.createElement('div');
        controlGroup.className = 'control-group';

        const labelElement = document.createElement('label');
        labelElement.textContent = label;
        controlGroup.appendChild(labelElement);

        const inputElement = document.createElement(type === 'select' ? 'select' : type);
        inputElement.name = name;
        inputElement.value = config.value;

        if (type === 'select') {
            config.options.forEach(option => {
                const optionElement = document.createElement('option');
                optionElement.value = option.value;
                optionElement.textContent = option.text;
                inputElement.appendChild(optionElement);
            });
        } else if (type === 'input') {
            inputElement.type = type;
            inputElement.min = config.min;
            inputElement.max = config.max;
            inputElement.step = config.step;
            inputElement.value = config.value;
        }

        controlGroup.appendChild(inputElement);

        // Add event listeners
        if (type === 'input' || type === 'select') {
            inputElement.addEventListener('input', (e) => {
                this.updateModuleParameter(e.target.name, e.target.value, e.target);
            });
        }

        return controlGroup;
    }

    updateModuleParameter(name, value, element) {
        const module = this.getModuleById(element.closest('.module').dataset.moduleId);
        if (module && module.params) {
            if (name === 'frequency') {
                module.params.frequency = parseFloat(value);
            } else if (name === 'volume') {
                module.params.volume = parseFloat(value);
            } else if (name === 'waveform') {
                module.params.waveform = value;
            } else if (name === 'resonance') {
                module.params.resonance = parseFloat(value);
            } else if (name === 'q') {
                module.params.q = parseFloat(value);
            } else if (name === 'attack') {
                module.params.attack = parseFloat(value);
            } else if (name === 'decay') {
                module.params.decay = parseFloat(value);
            } else if (name === 'sustain') {
                module.params.sustain = parseFloat(value);
            } else if (name === 'release') {
                module.params.release = parseFloat(value);
            } else if (name === 'decay') {
                module.params.decay = parseFloat(value);
            } else if (name === 'wet') {
                module.params.wet = parseFloat(value);
            } else if (name === 'roomSize') {
                module.params.roomSize = parseFloat(value);
            } else if (name === 'delayTime') {
                module.params.delayTime = parseFloat(value);
            } else if (name === 'feedback') {
                module.params.feedback = parseFloat(value);
            } else if (name === 'distortion') {
                module.params.distortion = parseFloat(value);
            }

            // Update audio node
            this.updateModuleAudioNode(module);

            // Update UI
            this.updateCurrentSound();
        }
    }

