    placeModule(x, y) {
        if (!this.draggedModule) return;

        const moduleType = this.draggedModule.dataset.type;
        const module = this.createModuleInstance(moduleType);
        module.x = x;
        module.y = y;
        module.element = this.createModuleElement(moduleType, module);
        module.element.dataset.moduleId = module.id;
        module.element.style.left = `${x - 100}px`;
        module.element.style.top = `${y - 50}px`;

        // Add to canvas
        this.synthModules.appendChild(module.element);

        // Add to modules array
        this.modules.push(module);

        // Add module to audio graph
        this.addModuleToAudioGraph(module);

        // Add module to settings panel
        this.showSettings(module);

        // Update UI
        this.updateCurrentSound();
    }

    addModuleToAudioGraph(module) {
        // Create audio node based on module type
        switch (module.type) {
            case 'sine':
            case 'square':
            case 'sawtooth':
            case 'triangle':
                this.createOscillatorNode(module);
                break;

            case 'lowpass':
            case 'highpass':
            case 'bandpass':
            case 'notch':
                this.createFilterNode(module);
                break;

            case 'adsr':
            case 'envelope':
                this.createEnvelopeNode(module);
                break;

            case 'reverb':
                this.createReverbNode(module);
                break;

            case 'delay':
                this.createDelayNode(module);
                break;

            case 'distortion':
                this.createDistortionNode(module);
                break;
        }
    }

    createOscillatorNode(module) {
        const oscillator = this.audioContext.createOscillator();
        oscillator.type = module.params.waveform;
        oscillator.frequency.setValueAtTime(module.params.frequency, this.audioContext.currentTime);
        oscillator.connect(this.masterGainNode);

        module.audioNode = oscillator;

        // Add to audio graph
        this.connectModuleToAudioGraph(module);
    }

    createFilterNode(module) {
        const filter = this.audioContext.createBiquadFilter();
        filter.type = module.type;
        filter.frequency.setValueAtTime(module.params.frequency, this.audioContext.currentTime);
        filter.Q.setValueAtTime(module.params.q, this.audioContext.currentTime);
        filter.connect(this.masterGainNode);

        module.audioNode = filter;

        // Add to audio graph
        this.connectModuleToAudioGraph(module);
    }

    createEnvelopeNode(module) {
        const envelope = this.audioContext.createGain();
        envelope.gain.setValueAtTime(0, this.audioContext.currentTime);
        envelope.connect(this.masterGainNode);

        module.audioNode = envelope;

        // Add to audio graph
        this.connectModuleToAudioGraph(module);
    }

    createReverbNode(module) {
        const reverb = this.audioContext.createConvolver();
        reverb.connect(this.masterGainNode);

        module.audioNode = reverb;

        // Add to audio graph
        this.connectModuleToAudioGraph(module);
    }

    createDelayNode(module) {
        const delay = this.audioContext.createDelay();
        delay.delayTime.setValueAtTime(module.params.delayTime, this.audioContext.currentTime);
        delay.connect(this.masterGainNode);

        module.audioNode = delay;

        // Add to audio graph
        this.connectModuleToAudioGraph(module);
    }

    createDistortionNode(module) {
        const distortion = this.audioContext.createWaveShaper();
        const curve = new Float32Array(4096);
        for (let i = 0; i < 4096; i++) {
            const x = i * 2 / 4096 - 1;
            curve[i] = (x < 0 ? -1 : 1) * (x * x * x * x * x);
        }
        distortion.curve = curve;
        distortion.connect(this.masterGainNode);

        module.audioNode = distortion;

        // Add to audio graph
        this.connectModuleToAudioGraph(module);
    }

    connectModuleToAudioGraph(module) {
        // Connect module to audio graph
        // This is a simplified version - in a real implementation, you would need to handle connections between modules
        if (module.type === 'sine' || module.type === 'square' || module.type === 'sawtooth' || module.type === 'triangle') {
            // Connect oscillator to master gain
            if (module.audioNode) {
                module.audioNode.connect(this.masterGainNode);
            }
        }
    }

    updateModuleAudioNode(module) {
        if (!module.audioNode) return;

        switch (module.type) {
            case 'sine':
            case 'square':
            case 'sawtooth':
            case 'triangle':
                if (module.audioNode) {
                    module.audioNode.frequency.setValueAtTime(module.params.frequency, this.audioContext.currentTime);
                }
                break;

            case 'lowpass':
            case 'highpass':
            case 'bandpass':
            case 'notch':
                if (module.audioNode) {
                    module.audioNode.frequency.setValueAtTime(module.params.frequency, this.audioContext.currentTime);
                    module.audioNode.Q.setValueAtTime(module.params.q, this.audioContext.currentTime);
                }
                break;

            case 'adsr':
            case 'envelope':
                if (module.audioNode) {
                    // Update envelope parameters
                    module.audioNode.gain.setValueAtTime(0, this.audioContext.currentTime);
                    module.audioNode.gain.setValueAtTime(module.params.sustain, this.audioContext.currentTime + module.params.attack);
                    module.audioNode.gain.exponentialRampToValueAtTime(0.001, this.audioContext.currentTime + module.params.attack + module.params.decay);
                }
                break;

            case 'reverb':
                if (module.audioNode) {
                    // Update reverb parameters
                    module.audioNode.gain.setValueAtTime(module.params.wet, this.audioContext.currentTime);
                }
                break;

            case 'delay':
                if (module.audioNode) {
                    module.audioNode.delayTime.setValueAtTime(module.params.delayTime, this.audioContext.currentTime);
                    module.audioNode.gain.setValueAtTime(module.params.wet, this.audioContext.currentTime);
                }
                break;

            case 'distortion':
                if (module.audioNode) {
                    module.audioNode.gain.setValueAtTime(module.params.wet, this.audioContext.currentTime);
                }
                break;
        }
    }

    showSettings(module) {
        this.settingsContent.innerHTML = '';

        const moduleType = module.type;
        const moduleParams = module.params;

        const settingsTitle = document.createElement('h3');
        settingsTitle.textContent = `${moduleType.charAt(0).toUpperCase() + moduleType.slice(1)} Settings`;
        this.settingsContent.appendChild(settingsTitle);

        const settingsContainer = document.createElement('div');
        settingsContainer.className = 'settings-container';
        this.settingsContent.appendChild(settingsContainer);

        // Add parameters based on module type
        switch (moduleType) {
            case 'sine':
            case 'square':
            case 'sawtooth':
            case 'triangle':
                this.addOscillatorSettings(settingsContainer, moduleParams);
                break;

            case 'lowpass':
            case 'highpass':
            case 'bandpass':
            case 'notch':
                this.addFilterSettings(settingsContainer, moduleParams);
                break;

            case 'adsr':
            case 'envelope':
                this.addEnvelopeSettings(settingsContainer, moduleParams);
                break;

            case 'reverb':
                this.addReverbSettings(settingsContainer, moduleParams);
                break;

            case 'delay':
                this.addDelaySettings(settingsContainer, moduleParams);
                break;

            case 'distortion':
                this.addDistortionSettings(settingsContainer, moduleParams);
                break;
        }

        // Add close button
        const closeButton = document.createElement('button');
        closeButton.textContent = 'Close';
        closeButton.addEventListener('click', () => {
            this.settingsPanel.style.display = 'none';
        });
        this.settingsContent.appendChild(closeButton);

        // Show settings panel
        this.settingsPanel.style.display = 'block';
    }

