document.addEventListener('DOMContentLoaded', () => {
    const synthCanvas = document.getElementById('synthCanvas');
    const modules = document.querySelectorAll('.module');

    // Add connection logic
    modules.forEach(module => {
        const inputPoint = module.querySelector('.connection-point[data-type="input"]');
        const outputPoint = module.querySelector('.connection-point[data-type="output"]');

        if (inputPoint && outputPoint) {
            inputPoint.addEventListener('mousedown', (e) => {
                e.preventDefault();
                // Start connection
                const startX = e.clientX;
                const startY = e.clientY;

                // Create connection line
                const connection = document.createElement('div');
                connection.className = 'connection-line';
                connection.style.position = 'absolute';
                connection.style.left = `${startX}px`;
                connection.style.top = `${startY}px`;
                connection.style.width = '0px';
                connection.style.height = '0px';
                connection.style.backgroundColor = '#4CAF50';
                connection.style.borderRadius = '2px';
                synthCanvas.appendChild(connection);

                // Store connection data
                connection.dataset.moduleId = module.dataset.moduleId;
                connection.dataset.connectionId = 'input';

                // Update connection position on mouse move
                document.addEventListener('mousemove', (e) => {
                    if (connection && connection.dataset.moduleId) {
                        connection.style.left = `${e.clientX}px`;
                        connection.style.top = `${e.clientY}px`;
                    }
                });

                // End connection on mouse up
                document.addEventListener('mouseup', (e) => {
                    if (connection && connection.dataset.moduleId) {
                        // Find target module
                        const targetModule = document.querySelector('.module[data-module-id]');
                        if (targetModule) {
                            // Connect modules
                            // In a real implementation, you would connect the modules
                            console.log(`Connecting ${module.dataset.moduleId} to ${targetModule.dataset.moduleId}`);
                        }

                        // Remove connection
                        synthCanvas.removeChild(connection);
                        document.removeEventListener('mousemove', () => {});
                        document.removeEventListener('mouseup', () => {});
                    }
                });
            });
        }
    });
});
