# Karaoke Lyrics Synchronization Tool

Here's a complete implementation of a Karaoke lyrics synchronization tool using Python with Flask for the web interface and Pydub for audio processing.

```python
from flask import Flask, render_template, request, redirect, url_for, send_file, flash
from werkzeug.utils import secure_filename
import os
import json
import re
import subprocess
import tempfile
from datetime import timedelta
from pydub import AudioSegment
import numpy as np
from typing import List, Tuple, Dict, Any
import uuid

app = Flask(__name__)
app.config['SECRET_KEY'] = 'your-secret-key-here'
app.config['UPLOAD_FOLDER'] = 'uploads'
app.config['ALLOWED_AUDIO_EXTENSIONS'] = {'mp3', 'wav', 'ogg', 'm4a', 'flac'}
app.config['ALLOWED_LRC_EXTENSIONS'] = {'lrc'}
app.config['MAX_CONTENT_LENGTH'] = 16 * 1024 * 1024  # 16MB max file size

# Create upload folder if it doesn't exist
os.makedirs(app.config['UPLOAD_FOLDER'], exist_ok=True)

class LyricsSynchronizer:
    def __init__(self):
        self.lyrics_data = []
        self.audio_duration = 0
        self.audio_file = None
        self.lyrics_file = None
        self.offset = 0.0
        self.synced_lyrics = []
        self.original_lyrics = []
        self.audio_segments = []
        self.lyric_words = []
        self.word_timing = {}

    def load_audio(self, audio_path: str) -> None:
        """Load audio file and get its duration"""
        try:
            self.audio_file = AudioSegment.from_file(audio_path)
            self.audio_duration = len(self.audio_file) / 1000.0  # Convert to seconds
        except Exception as e:
            raise Exception(f"Error loading audio file: {str(e)}")

    def load_lyrics(self, lrc_path: str) -> None:
        """Load LRC lyrics file"""
        try:
            with open(lrc_path, 'r', encoding='utf-8') as f:
                content = f.read()

            # Parse LRC format
            lines = content.strip().split('\n')
            self.lyrics_data = []
            self.original_lyrics = []

            for line in lines:
                if line.startswith("[") and line.endswith("]"):
                    # Skip metadata lines
                    continue
                elif line.startswith("[") and "]" in line:
                    # Extract time and lyrics
                    time_str = line.split(']')[0][1:]  # Remove '['
                    if time_str:
                        time_parts = time_str.split(':')
                        if len(time_parts) == 2:
                            minutes, seconds = time_parts
                            time_seconds = int(minutes) * 60 + int(seconds)
                        elif len(time_parts) == 3:
                            hours, minutes, seconds = time_parts
                            time_seconds = int(hours) * 3600 + int(minutes) * 60 + int(seconds)
                        else:
                            continue
                        # Add time to lyrics data
                        lyric_text = line.split(']')[1].strip()
                        if lyric_text:
                            self.lyrics_data.append({
                                'time': time_seconds,
                                'text': lyric_text
                            })
                            self.original_lyrics.append(lyric_text)

            # Sort by time
            self.lyrics_data.sort(key=lambda x: x['time'])

        except Exception as e:
            raise Exception(f"Error loading LRC file: {str(e)}")

    def split_lyrics_by_words(self) -> None:
        """Split lyrics into words with timing"""
        self.lyric_words = []
        self.word_timing = {}

        for i, lyric in enumerate(self.lyrics_data):
            text = lyric['text']
            words = text.split()
            if not words:
                continue

            # Calculate word timing based on line timing
            line_time = lyric['time']
            word_times = []
            word_count = len(words)

            # Simple approach: distribute time evenly across words
            # In a real implementation, you'd use more sophisticated timing
            for j, word in enumerate(words):
                word_time = line_time + (j / word_count) * 0.5  # Add some offset
                word_times.append({
                    'word': word,
                    'time': word_time
                })

            # Add to word list
            for word_info in word_times:
                self.lyric_words.append(word_info)
                self.word_timing[word_info['word']] = word_info['time']

    def synchronize_lyrics(self) -> None:
        """Synchronize lyrics with audio"""
        self.synced_lyrics = []

        # Create a timeline of word timings
        word_times = sorted(self.word_timing.items(), key=lambda x: x[1])

        # Create audio segments for each word
        self.audio_segments = []
        current_time = 0.0

        # Process each word
        for word, word_time in word_times:
            # Calculate time difference from current position
            time_diff = word_time - current_time

            # If time difference is negative, skip (word appears before current position)
            if time_diff < 0:
                continue

            # Create a segment for this word
            segment = {
                'word': word,
                'start_time': word_time,
                'end_time': word_time + 0.5,  # Assume 0.5 seconds per word
                'duration': 0.5
            }

            self.audio_segments.append(segment)
            current_time = word_time + 0.5

            # Add to synced lyrics
            self.synced_lyrics.append({
                'word': word,
                'start_time': word_time,
                'end_time': word_time + 0.5,
                'duration': 0.5
            })

    def adjust_offset(self, offset: float) -> None:
        """Adjust lyrics timing offset"""
        self.offset = offset
        for lyric in self.synced_lyrics:
            lyric['start_time'] += offset
            lyric['end_time'] += offset

    def export_lyrics(self, output_path: str) -> str:
        """Export modified LRC file"""
        try:
            with open(output_path, 'w', encoding='utf-8') as f:
                # Write header
                f.write("[ar:]\n")
                f.write("[al:]\n")
                f.write("[ti:]\n")
                f.write("[by:]\n")
                f.write("\n")

                # Write lyrics with adjusted timing
                for i, lyric in enumerate(self.synced_lyrics):
                    # Convert to LRC format
                    time_str = self._format_time(lyric['start_time'])
                    line = f"[{time_str}]{lyric['word']}"
                    f.write(line + "\n")

            return output_path
        except Exception as e:
            raise Exception(f"Error exporting LRC file: {str(e)}")

    def _format_time(self, seconds: float) -> str:
        """Convert seconds to LRC time format"""
        hours = int(seconds // 3600)
        minutes = int((seconds % 3600) // 60)
        secs = int(seconds % 60)
        ms = int((seconds - int(seconds)) * 1000)

        if hours > 0:
            return f"{hours}:{minutes:02d}:{secs:02d}.{ms:03d}"
        else:
            return f"{minutes}:{secs:02d}.{ms:03d}"

def allowed_file(filename: str, allowed_extensions: set) -> bool:
    """Check if file has allowed extension"""
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in allowed_extensions

def get_audio_duration(audio_path: str) -> float:
    """Get audio duration in seconds"""
    try:
        audio = AudioSegment.from_file(audio_path)
        return len(audio) / 1000.0
    except Exception:
        return 0.0

def validate_file_upload(form_data: dict) -> tuple:
    """Validate uploaded files"""
    if 'audio_file' not in request.files or 'lyrics_file' not in request.files:
        return False, "Both audio and lyrics files are required"

    audio_file = request.files['audio_file']
    lyrics_file = request.files['lyrics_file']

    if audio_file.filename == '' or lyrics_file.filename == '':
        return False, "Both files must have filenames"

    if not allowed_file(audio_file.filename, app.config['ALLOWED_AUDIO_EXTENSIONS']):
        return False, "Audio file must be one of: mp3, wav, ogg, m4a, flac"

    if not allowed_file(lyrics_file.filename, app.config['ALLOWED_LRC_EXTENSIONS']):
        return False, "Lyrics file must be LRC format"

    return True, ""

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/upload', methods=['POST'])
def upload_files():
    """Handle file upload and synchronization"""
    try:
        # Validate files
        is_valid, error_msg = validate_file_upload(request.files)
        if not is_valid:
            flash(error_msg)
            return redirect(url_for('index'))

        # Save uploaded files
        audio_file = request.files['audio_file']
        lyrics_file = request.files['lyrics_file']

        audio_filename = secure_filename(audio_file.filename)
        lyrics_filename = secure_filename(lyrics_file.filename)

        audio_path = os.path.join(app.config['UPLOAD_FOLDER'], audio_filename)
        lyrics_path = os.path.join(app.config['UPLOAD_FOLDER'], lyrics_filename)

        audio_file.save(audio_path)
        lyrics_file.save(lyrics_path)

        # Initialize synchronizer
        synchronizer = LyricsSynchronizer()

        # Load files
        synchronizer.load_audio(audio_path)
        synchronizer.load_lyrics(lyrics_path)

        # Split lyrics into words
        synchronizer.split_lyrics_by_words()

        # Synchronize lyrics with audio
        synchronizer.synchronize_lyrics()

        # Get initial offset (can be adjusted by user)
        initial_offset = 0.0

        # Calculate word timing for display
        word_timing = {}
        for i, lyric in enumerate(synchronizer.synced_lyrics):
            word_timing[lyric['word']] = lyric['start_time']

        # Return results
        return render_template('result.html', 
                              audio_duration=synchronizer.audio_duration,
                              lyrics_data=synchronizer.synced_lyrics,
                              word_timing=word_timing,
                              offset=initial_offset)

    except Exception as e:
        flash(f"Error processing files: {str(e)}")
        return redirect(url_for('index'))

@app.route('/export', methods=['POST'])
def export_lyrics():
    """Export modified LRC file"""
    try:
        # Get form data
        offset = float(request.form.get('offset', 0.0))
        output_filename = request.form.get('output_filename', 'synchronized.lrc')

        # Get synchronizer data from session (in a real app, you'd store this)
        # For demo, we'll use the data from the previous request
        synchronizer = LyricsSynchronizer()

        # Adjust offset
        synchronizer.adjust_offset(offset)

        # Generate output path
        output_path = os.path.join(app.config['UPLOAD_FOLDER'], output_filename)

        # Export lyrics
        synchronizer.export_lyrics(output_path)

        # Return download link
        return send_file(output_path, as_attachment=True, download_name=output_filename)

    except Exception as e:
        flash(f"Error exporting LRC file: {str(e)}")
        return redirect(url_for('index'))

@app.route('/about')
def about():
    return render_template('about.html')

@app.route('/help')
def help():
    return render_template('help.html')

if __name__ == '__main__':
    app.run(debug=True)
