                        bullets.splice(j, 1);
                        j--;

                        // Check if asteroid is destroyed
                        if (asteroid.userData.health <= 0) {
                            // Create explosion particles
                            createExplosionParticles(asteroid.position);

                            // Play explosion sound
                            explosionSound.play().catch(e => console.log("Explosion sound autoplay blocked"));

                            // Add score
                            score += 10;
                            document.getElementById('score').textContent = score;

                            // Create new asteroids
                            createNewAsteroids(asteroid);

                            // Remove asteroid
                            scene.remove(asteroid);
                            asteroids.splice(i, 1);
                            i--;
                            break;
                        }
                    }
                }
            }
        }

        // Create new asteroids after destroying one
        function createNewAsteroids(asteroid) {
            const size = asteroid.userData.size;
            const newAsteroidSize = size * 0.5;

            // Create 3 smaller asteroids
            for (let i = 0; i < 3; i++) {
                const newAsteroid = createAsteroid();
                newAsteroid.userData.size = newAsteroidSize;
                newAsteroid.userData.health = 1;
                newAsteroid.position.copy(asteroid.position);
                newAsteroid.userData.velocity = new THREE.Vector3(
                    (Math.random() - 0.5) * 0.5,
                    (Math.random() - 0.5) * 0.5,
                    (Math.random() - 0.5) * 0.5
                );
                scene.add(newAsteroid);
                asteroids.push(newAsteroid);
            }
        }

        // Update bullets
        function updateBullets() {
            for (let i = 0; i < bullets.length; i++) {
                const bullet = bullets[i];

                // Move bullet
                bullet.position.add(bullet.userData.velocity);

                // Remove bullet if it goes out of bounds
                if (bullet.position.x < -20 || bullet.position.x > 20 ||
                    bullet.position.y < -20 || bullet.position.y > 20 ||
                    bullet.position.z < -20 || bullet.position.z > 20) {
                    scene.remove(bullet);
                    bullets.splice(i, 1);
                    i--;
                }
            }
        }

        // Create explosion particles
        function createExplosionParticles(position) {
            const geometry = new THREE.BufferGeometry();
            const count = 100;
            const positions = new Float32Array(count * 3);
            const velocities = new Float32Array(count * 3);
            const colors = new Float32Array(count * 3);

            for (let i = 0; i < count; i++) {
                const i3 = i * 3;
                positions[i3] = (Math.random() - 0.5) * 2;
                positions[i3 + 1] = (Math.random() - 0.5) * 2;
                positions[i3 + 2] = (Math.random() - 0.5) * 2;

                velocities[i3] = (Math.random() - 0.5) * 0.5;
                velocities[i3 + 1] = (Math.random() - 0.5) * 0.5;
                velocities[i3 + 2] = (Math.random() - 0.5) * 0.5;

                colors[i3] = 1;
                colors[i3 + 1] = 0.5;
                colors[i3 + 2] = 0;
            }

            geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
            geometry.setAttribute('velocity', new THREE.Float32BufferAttribute(velocities, 3));
            geometry.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));

            const material = new THREE.PointsMaterial({
                size: 0.1,
                vertexColors: true,
                transparent: true,
                opacity: 0.8,
                blending: THREE.AdditiveBlending
            });

            const explosion = new THREE.Points(geometry, material);
            explosion.position.copy(position);
            explosion.userData.life = 100;
            scene.add(explosion);
            particles.push(explosion);
        }

        // Create shield impact particles
        function createShieldImpactParticles() {
            const geometry = new THREE.BufferGeometry();
            const count = 50;
            const positions = new Float32Array(count * 3);
            const velocities = new Float32Array(count * 3);
            const colors = new Float32Array(count * 3);

            for (let i = 0; i < count; i++) {
                const i3 = i * 3;
                positions[i3] = (Math.random() - 0.5) * 2;
                positions[i3 + 1] = (Math.random() - 0.5) * 2;
                positions[i3 + 2] = (Math.random() - 0.5) * 2;

                velocities[i3] = (Math.random() - 0.5) * 0.5;
                velocities[i3 + 1] = (Math.random() - 0.5) * 0.5;
                velocities[i3 + 2] = (Math.random() - 0.5) * 0.5;

                colors[i3] = 1;
                colors[i3 + 1] = 0.5;
                colors[i3 + 2] = 0;
            }

            geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
            geometry.setAttribute('velocity', new THREE.Float32BufferAttribute(velocities, 3));
            geometry.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));

            const material = new THREE.PointsMaterial({
                size: 0.1,
                vertexColors: true,
                transparent: true,
                opacity: 0.8,
                blending: THREE.AdditiveBlending
            });

            const shieldImpact = new THREE.Points(geometry, material);
            shieldImpact.position.copy(playerMesh.position);
            shieldImpact.userData.life = 100;
            scene.add(shieldImpact);
            particles.push(shieldImpact);
        }

        // Update lighting
        function updateLighting() {
            // Change light color based on time
            const time = Date.now() / 1000;
            const color = new THREE.Color();

            // Cycle through different colors
            const hue = (time * 0.01) % 1;
            color.setHSL(hue, 0.8, 0.5);
            light.color.copy(color);

            // Change intensity
            const intensity = Math.sin(time * 0.1) * 0.5 + 0.5;
            light.intensity = intensity;
        }

        // Handle keyboard input
        const keys = {};
        function onKeyDown(event) {
            keys[event.key.toLowerCase()] = true;

            // Shoot
            if (event.key === ' ') {
                shoot();
            }

            // Pause
            if (event.key === 'Escape') {
                togglePause();
            }
        }

        function onKeyUp(event) {
            keys[event.key.toLowerCase()] = false;
        }

        // Handle mouse input
        let mouseX = 0;
        let mouseY = 0;
        let mouseDown = false;
        function onMouseMove(event) {
            mouseX = (event.clientX / window.innerWidth) * 2 - 1;
            mouseY = -(event.clientY / window.innerHeight) * 2 + 1;
        }

        function onMouseDown(event) {
            mouseDown = true;
            shoot();
        }

        function onClick(event) {
            shoot();
        }

        function preventContextMenu(event) {
            event.preventDefault();
        }

        // Shoot function
        function shoot() {
            if (mouseDown) {
                // Create bullet
                const bulletGeometry = new THREE.SphereGeometry(0.1, 16, 16);
                const bulletMaterial = new THREE.MeshBasicMaterial({ color: 0xff0000 });
                const bullet = new THREE.Mesh(bulletGeometry, bulletMaterial);
                bullet.position.copy(playerMesh.position);
                bullet.userData.velocity = new THREE.Vector3(
                    mouseX * 0.5,
                    mouseY * 0.5,
                    0
                );
                bullet.userData.velocity.normalize();
                bullet.userData.velocity.multiplyScalar(0.5);
                bullet.userData.life = 100;
                scene.add(bullet);
                bullets.push(bullet);

                // Play shoot sound
                shootSound.play().catch(e => console.log("Shoot sound autoplay blocked"));
            }
        }

        // Handle window resize
        function onWindowResize() {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        }

        // Toggle pause
        function togglePause() {
            isPaused = !isPaused;
            if (isPaused) {
                // Pause game
                cancelAnimationFrame(gameLoop);
            } else {
                // Resume game
                gameLoop = requestAnimationFrame(gameLoop);
            }
        }

        // Start the game
        init();
    </script>
</body>
</html>
```

