const express = require('express');
const cors = require('cors');
const puppeteer = require('puppeteer');
const path = require('path');
const fs = require('fs').promises;

const app = express();
const PORT = process.env.PORT || 3000;

// Middleware
app.use(cors());
app.use(express.json());
app.use(express.static('public'));

// Serve index.html
app.get('/', (req, res) => {
  res.sendFile(path.join(__dirname, 'public', 'index.html'));
});

// Screenshot endpoint
app.post('/screenshot', async (req, res) => {
  const { url } = req.body;

  if (!url) {
    return res.status(400).json({ error: 'URL is required' });
  }

  try {
    const browser = await puppeteer.launch({
      headless: true,
      args: ['--no-sandbox', '--disable-setuid-sandbox']
    });

    const page = await browser.newPage();
    await page.setViewport({ width: 1280, height: 720 });

    // Navigate to URL
    await page.goto(url, { waitUntil: 'networkidle2' });

    // Take screenshot
    const screenshotPath = path.join(__dirname, 'screenshots', `${Date.now()}.png`);
    await page.screenshot({ path: screenshotPath, type: 'png', quality: 100 });

    // Send response with download link
    const downloadLink = `/screenshots/${path.basename(screenshotPath)}`;
    res.json({
      success: true,
      downloadUrl: downloadLink,
      screenshotPath: screenshotPath
    });

    await browser.close();
  } catch (error) {
    console.error('Error taking screenshot:', error);
    res.status(500).json({ error: 'Failed to capture screenshot' });
  }
});

// Serve static screenshots
app.use('/screenshots', express.static('screenshots'));

app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

