document.addEventListener('DOMContentLoaded', () => {
  const urlInput = document.getElementById('urlInput');
  const captureBtn = document.getElementById('captureBtn');
  const resultDiv = document.getElementById('result');
  const downloadLink = document.getElementById('downloadLink');
  const downloadAnchor = document.getElementById('downloadAnchor');

  captureBtn.addEventListener('click', async () => {
    const url = urlInput.value.trim();
    if (!url) {
      resultDiv.innerHTML = '<p style="color: red;">Please enter a valid URL.</p>';
      return;
    }

    resultDiv.innerHTML = '<p>Processing... Please wait.</p>';
    downloadLink.style.display = 'none';

    try {
      const response = await fetch('/screenshot', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ url })
      });

      const data = await response.json();

      if (data.success) {
        resultDiv.innerHTML = `<p>✅ Screenshot captured successfully!</p>`;
        downloadAnchor.href = data.downloadUrl;
        downloadAnchor.textContent = 'Download Screenshot';
        downloadLink.style.display = 'block';
      } else {
        resultDiv.innerHTML = `<p style="color: red;">${data.error}</p>`;
      }
    } catch (error) {
      console.error('Error:', error);
      resultDiv.innerHTML = `<p style="color: red;">Failed to capture screenshot. Try again.</p>`;
    }
  });
});
