    const instruments = await Instrument.find()
      .populate('createdBy', 'name email role')
      .sort({ name: 1 });
    res.json(instruments);
  } catch (error) {
    res.status(500).json({ message: error.message });
  }
};

// Search instruments
exports.searchInstruments = async (req, res) => {
  try {
    const { query, status, type, location } = req.query;

    let queryObj = {};

    if (query) {
      queryObj.$or = [
        { name: { $regex: query, $options: 'i' } },
        { type: { $regex: query, $options: 'i' } },
        { manufacturer: { $regex: query, $options: 'i' } },
        { model: { $regex: query, $options: 'i' } }
      ];
    }

    if (status) {
      queryObj.status = status;
    }

    if (type) {
      queryObj.type = type;
    }

    if (location) {
      queryObj.location = location;
    }

    const instruments = await Instrument.find(queryObj)
      .populate('createdBy', 'name email role')
      .sort({ name: 1 });

    res.json(instruments);
  } catch (error) {
    res.status(500).json({ message: error.message });
  }
};

// Get instrument by ID
exports.getInstrumentById = async (req, res) => {
  try {
    const instrument = await Instrument.findById(req.params.id)
      .populate('createdBy', 'name email role')
      .populate({
        path: 'maintenanceHistory',
        model: 'Maintenance',
        options: { sort: { date: -1 } }
      });

    if (!instrument) {
      return res.status(404).json({ message: 'Instrument not found' });
    }

    res.json(instrument);
  } catch (error) {
    res.status(500).json({ message: error.message });
  }
};

