    const { instrumentId, technician, description, startTime, endTime, status, notes } = req.body;

    // Validate required fields
    if (!instrumentId || !technician || !description || !startTime || !endTime) {
      return res.status(400).json({ message: 'All required fields must be provided' });
    }

    const newMaintenance = new Maintenance({
      instrumentId,
      technician,
      description,
      date: new Date(),
      startTime: new Date(startTime),
      endTime: new Date(endTime),
      status: status || 'scheduled',
      notes: notes || '',
      createdBy: req.user.id
    });

    const savedMaintenance = await newMaintenance.save();

    // Update instrument's last maintenance date
    const instrument = await Instrument.findById(instrumentId);
    if (instrument) {
      instrument.lastMaintenance = new Date();
      instrument.nextMaintenance = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000); // 30 days from now
      await instrument.save();
    }

    res.status(201).json(savedMaintenance);
  } catch (error) {
    res.status(500).json({ message: error.message });
  }
};

// Update maintenance record
exports.updateMaintenanceRecord = async (req, res) => {
  try {
    const { technician, description, startTime, endTime, status, notes } = req.body;

    const maintenance = await Maintenance.findById(req.params.id);
    if (!maintenance) {
      return res.status(404).json({ message: 'Maintenance record not found' });
    }

    // Update fields if provided
    if (technician) maintenance.technician = technician;
    if (description) maintenance.description = description;
    if (startTime) maintenance.startTime = new Date(startTime);
    if (endTime) maintenance.endTime = new Date(endTime);
    if (status) maintenance.status = status;
    if (notes) maintenance.notes = notes;

    maintenance.updatedAt = Date.now();

    const updatedMaintenance = await maintenance.save();

    res.json(updatedMaintenance);
  } catch (error) {
    res.status(500).json({ message: error.message });
  }
};

// Delete maintenance record
exports.deleteMaintenanceRecord = async (req, res) => {
  try {
    const maintenance = await Maintenance.findById(req.params.id);
    if (!maintenance) {
      return res.status(404).json({ message: 'Maintenance record not found' });
    }

    await maintenance.deleteOne();

    res.json({ message: 'Maintenance record deleted successfully' });
  } catch (error) {
    res.status(500).json({ message: error.message });
  }
};
