    const { name, value } = e.target;
    setNewInstrument(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleMaintenanceChange = (e) => {
    const { name, value } = e.target;
    setMaintenanceForm(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const validateInstrument = () => {
    const errors = [];
    if (!newInstrument.name.trim()) errors.push('Name is required');
    if (!newInstrument.type.trim()) errors.push('Type is required');
    if (!newInstrument.manufacturer.trim()) errors.push('Manufacturer is required');
    if (!newInstrument.model.trim()) errors.push('Model is required');
    if (!newInstrument.serialNumber.trim()) errors.push('Serial Number is required');
    if (!newInstrument.purchaseDate.trim()) errors.push('Purchase Date is required');
    if (!newInstrument.location.trim()) errors.push('Location is required');

    setInstrumentError(errors.join(', '));
    return errors.length === 0;
  };

