    const errors = [];
    if (!maintenanceForm.instrumentId.trim()) errors.push('Instrument ID is required');
    if (!maintenanceForm.technician.trim()) errors.push('Technician is required');
    if (!maintenanceForm.description.trim()) errors.push('Description is required');
    if (!maintenanceForm.startTime.trim()) errors.push('Start Time is required');
    if (!maintenanceForm.endTime.trim()) errors.push('End Time is required');

    setMaintenanceError(errors.join(', '));
    return errors.length === 0;
  };

