// frontend/src/context/AuthContext.js
import React, { createContext, useContext, useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

const AuthContext = createContext();

export const useAuth = () => {
  return useContext(AuthContext);
};

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    const checkAuth = async () => {
      try {
        // In a real app, you would check if the user is authenticated
        // For now, we'll just simulate authentication
        const isAuthenticated = localStorage.getItem('token');
        if (isAuthenticated) {
          setUser({ id: '1', name: 'Admin User', email: 'admin@example.com', role: 'admin' });
        }
      } catch (error) {
        console.error('Error checking authentication:', error);
      } finally {
        setLoading(false);
      }
    };

    checkAuth();
  }, []);

  const login = async (email, password) => {
    try {
      // In a real app, you would make an API call to authenticate the user
      // For now, we'll just simulate login
      localStorage.setItem('token', 'fake-token');
      setUser({ id: '1', name: 'Admin User', email: 'admin@example.com', role: 'admin' });
      return true;
    } catch (error) {
      throw error;
    }
  };

  const logout = () => {
    localStorage.removeItem('token');
    setUser(null);
    navigate('/login');
  };

  const value = {
    user,
    loading,
    login,
    logout
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
};
