```jsx
// frontend/src/hooks/useInstruments.js
import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';

const useInstruments = () => {
  const [instruments, setInstruments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [searchQuery, setSearchQuery] = useState('');

  const navigate = useNavigate();

  const fetchInstruments = async (query = '') => {
    try {
      setLoading(true);
      const response = await axios.get('/api/instruments', {
        params: { query, status: 'available', type: '', location: '' }
      });
      setInstruments(response.data);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const searchInstruments = async (query) => {
    try {
      setLoading(true);
      const response = await axios.get('/api/instruments/search', {
        params: { query, status: 'available', type: '', location: '' }
      });
      setInstruments(response.data);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchInstruments();
  }, []);

  return {
    instruments,
    loading,
    error,
    searchInstruments
  };
};

export default useInstruments;
