      query = { ...query, price: 1 };
    } else if (sort === 'posted') {
      query = { ...query, postedAt: -1 };
    } else if (sort === 'rating') {
      query = { ...query, sellerRating: -1 };
    } else {
      query = { ...query, postedAt: -1 };
    }

    const products = await Product.find(query)
      .populate('seller', 'username profilePicture rating')
