  }
};

// Get product by ID
exports.getProductById = async (req, res) => {
  try {
    const product = await Product.findById(req.params.id)
      .populate('seller', 'username profilePicture rating')
      .populate('negotiations', 'status buyerOffer sellerOffer');

    if (!product) {
      return res.status(404).json({ message: 'Product not found' });
    }

    res.json(product);
  } catch (error) {
    res.status(500).json({ message: error.message });
  }
};

// Create new product
exports.createProduct = async (req, res) => {
  try {
    const { title, description, price, category, condition, images, location, seller } = req.body;

    // Validate required fields
    if (!title || !description || !price || !category || !condition || !location) {
      return res.status(400).json({ message: 'All fields are required' });
    }

    // Create product
    const product = new Product({
      title,
      description,
      price,
      category,
      condition,
      images,
      seller,
      sellerName: req.user.username,
      sellerRating: req.user.rating,
      location
    });

    const savedProduct = await product.save();

    // Update seller's product count
    await User.findByIdAndUpdate(req.user._id, { $inc: { productCount: 1 } });

    res.status(201).json(savedProduct);
  } catch (error) {
    res.status(400).json({ message: error.message });
  }
};

// Update product
exports.updateProduct = async (req, res) => {
  try {
    const product = await Product.findById(req.params.id);

    if (!product) {
      return res.status(404).json({ message: 'Product not found' });
    }

    if (product.seller.toString() !== req.user._id.toString()) {
      return res.status(403).json({ message: 'You can only update your own products' });
    }

    Object.assign(product, req.body);
    await product.save();

    res.json(product);
  } catch (error) {
    res.status(400).json({ message: error.message });
  }
};

// Delete product
exports.deleteProduct = async (req, res) => {
  try {
    const product = await Product.findById(req.params.id);

    if (!product) {
      return res.status(404).json({ message: 'Product not found' });
    }

    if (product.seller.toString() !== req.user._id.toString()) {
      return res.status(403).json({ message: 'You can only delete your own products' });
    }

    await product.remove();
    await User.findByIdAndUpdate(req.user._id, { $inc: { productCount: -1 } });

    res.json({ message: 'Product deleted successfully' });
  } catch (error) {
    res.status(500).json({ message: error.message });
  }
};

// Start negotiation
exports.startNegotiation = async (req, res) => {
  try {
    const { productId, offerPrice } = req.body;

    const product = await Product.findById(productId);
    if (!product) {
      return res.status(404).json({ message: 'Product not found' });
    }

    if (product.seller.toString() === req.user._id.toString()) {
      return res.status(400).json({ message: 'You cannot negotiate with yourself' });
    }

    if (!product.negotiable) {
      return res.status(400).json({ message: 'Negotiation is not allowed for this product' });
    }

    if (offerPrice <= 0) {
      return res.status(400).json({ message: 'Offer price must be greater than 0' });
    }

    if (offerPrice > product.price) {
      return res.status(400).json({ message: 'Offer price cannot be higher than the original price' });
    }

    const negotiation = new Negotiation({
      product: productId,
      buyer: req.user._id,
      seller: product.seller,
      initialPrice: product.price,
      buyerOffer: offerPrice,
      sellerOffer: product.price,
      status: 'Pending'
    });

    await negotiation.save();

    // Update product with negotiation
    await Product.findByIdAndUpdate(productId, { $push: { negotiations: negotiation._id } });

    res.status(201).json(negotiation);
  } catch (error) {
    res.status(400).json({ message: error.message });
  }
};

// Accept negotiation
exports.acceptNegotiation = async (req, res) => {
  try {
    const { negotiationId } = req.body;

    const negotiation = await Negotiation.findById(negotiationId);
    if (!negotiation) {
      return res.status(404).json({ message: 'Negotiation not found' });
    }

    if (negotiation.status !== 'Pending') {
      return res.status(400).json({ message: 'Negotiation is not in pending state' });
    }

    if (negotiation.seller.toString() !== req.user._id.toString()) {
      return res.status(403).json({ message: 'You are not the seller of this negotiation' });
    }

    // Update negotiation status
    negotiation.status = 'Accepted';
    negotiation.sellerOffer = negotiation.buyerOffer;

    // Update product status to 'Sold'
    const product = await Product.findById(negotiation.product);
    if (product) {
      product.status = 'Sold';
      await product.save();
    }

    // Update cart with negotiation
    const cart = await Cart.findOne({ user: negotiation.buyer });
    if (cart) {
      const itemIndex = cart.items.findIndex(item => item.product.toString() === negotiation.product.toString());
      if (itemIndex !== -1) {
        cart.items[itemIndex].negotiatedPrice = negotiation.buyerOffer;
        cart.items[itemIndex].negotiationId = negotiation._id;
        cart.totalPrice = cart.items.reduce((total, item) => total + (item.negotiatedPrice || item.price) * item.quantity, 0);
        await cart.save();
      }
    }

    await negotiation.save();

    res.json({ message: 'Negotiation accepted successfully', negotiation });
  } catch (error) {
    res.status(400).json({ message: error.message });
  }
};

// Reject negotiation
exports.rejectNegotiation = async (req, res) => {
  try {
    const { negotiationId } = req.body;

    const negotiation = await Negotiation.findById(negotiationId);
    if (!negotiation) {
      return res.status(404).json({ message: 'Negotiation not found' });
    }

    if (negotiation.status !== 'Pending') {
      return res.status(400).json({ message: 'Negotiation is not in pending state' });
    }

    if (negotiation.seller.toString() !== req.user._id.toString()) {
      return res.status(403).json({ message: 'You are not the seller of this negotiation' });
    }

    negotiation.status = 'Rejected';
    await negotiation.save();

    res.json({ message: 'Negotiation rejected successfully', negotiation });
  } catch (error) {
    res.status(400).json({ message: error.message });
  }
};
