import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useAuth } from '../../hooks/useAuth';
import './ProductDetail.css';
import { useNavigate } from 'react-router-dom';

const ProductDetail = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { user } = useAuth();
  const [product, setProduct] = useState(null);
  const [negotiation, setNegotiation] = useState(null);
  const [showNegotiationModal, setShowNegotiationModal] = useState(false);
  const [negotiationPrice, setNegotiationPrice] = useState('');
  const [negotiationMessages, setNegotiationMessages] = useState([]);
  const [isNegotiationLoading, setIsNegotiationLoading] = useState(false);
  const [negotiationStatus, setNegotiationStatus] = useState(null);

  useEffect(() => {
    const fetchProduct = async () => {
      try {
        const response = await fetch(`/api/products/${id}`);
        const data = await response.json();
        setProduct(data);
      } catch (error) {
        console.error('Error fetching product:', error);
      }
    };

    fetchProduct();
  }, [id]);

  const handleNegotiate = async () => {
    if (!negotiationPrice || parseFloat(negotiationPrice) <= 0) {
      alert('Please enter a valid offer price');
      return;
    }

    setIsNegotiationLoading(true);
    try {
      const response = await fetch(`/api/products/${id}/negotiate`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          offerPrice: parseFloat(negotiationPrice)
        }),
      });

      const data = await response.json();
      if (response.ok) {
        setNegotiation(data);
        setNegotiationStatus('Pending');
        setShowNegotiationModal(true);
        setNegotiationPrice('');
      } else {
        alert('Failed to start negotiation');
      }
    } catch (error) {
      console.error('Error starting negotiation:', error);
      alert('Failed to start negotiation');
    } finally {
      setIsNegotiationLoading(false);
    }
  };

  const handleAcceptNegotiation = async () => {
    try {
      const response = await fetch(`/api/negotiations/${negotiation._id}/accept`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      const data = await response.json();
      if (response.ok) {
        alert('Negotiation accepted successfully!');
        setShowNegotiationModal(false);
        setNegotiationStatus('Accepted');
        // Update product status to 'Sold'
        setProduct(prev => ({
          ...prev,
          status: 'Sold'
        }));
      } else {
        alert('Failed to accept negotiation');
      }
    } catch (error) {
      console.error('Error accepting negotiation:', error);
      alert('Failed to accept negotiation');
    }
  };

  const handleRejectNegotiation = async () => {
    try {
      const response = await fetch(`/api/negotiations/${negotiation._id}/reject`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      const data = await response.json();
      if (response.ok) {
        alert('Negotiation rejected successfully!');
        setShowNegotiationModal(false);
        setNegotiationStatus('Rejected');
      } else {
        alert('Failed to reject negotiation');
      }
    } catch (error) {
      console.error('Error rejecting negotiation:', error);
      alert('Failed to reject negotiation');
    }
  };

  const handleSendMessage = async () => {
    if (!negotiationPrice) {
      alert('Please enter a message');
      return;
    }

    try {
      const response = await fetch(`/api/negotiations/${negotiation._id}/messages`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          sender: 'buyer',
          content: negotiationPrice
        }),
      });

      const data = await response.json();
      if (response.ok) {
        setNegotiationMessages(prev => [...prev, data]);
        setNegotiationPrice('');
      } else {
        alert('Failed to send message');
      }
    } catch (error) {
      console.error('Error sending message:', error);
      alert('Failed to send message');
