        alert('Failed to accept negotiation');
      }
    } catch (error) {
      console.error('Error accepting negotiation:', error);
      alert('Failed to accept negotiation');
    }
  };

  const handleRejectNegotiation = async () => {
    try {
      const response = await fetch(`/api/negotiations/${negotiationId}/reject`, {
        method: 'PUT',
      });

      const data = await response.json();
      if (response.ok) {
        alert('Negotiation rejected successfully!');
        setShowNegotiationModal(false);
      } else {
        alert('Failed to reject negotiation');
      }
    } catch (error) {
      console.error('Error rejecting negotiation:', error);
      alert('Failed to reject negotiation');
    }
  };

  const handleSendMessage = async () => {
    if (!negotiationPrice) {
      alert('Please enter a message');
      return;
    }

    try {
      const response = await fetch(`/api/negotiations/${negotiationId}/messages`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          sender: 'buyer',
          content: negotiationPrice
        }),
      });

      const data = await response.json();
      if (response.ok) {
        // Update negotiation messages
        setNegotiations(prev => prev.map(negotiation => 
          negotiation._id === negotiationId ? { ...negotiation, messages: [...negotiation.messages, data] } : negotiation
        ));
        setNegotiationPrice('');
      } else {
        alert('Failed to send message');
      }
    } catch (error) {
      console.error('Error sending message:', error);
      alert('Failed to send message');
    }
  };

  const handleRemoveItem = async (itemId) => {
    try {
      const response = await fetch(`/api/cart/${itemId}`, {
        method: 'DELETE',
