### server/middleware/chunkMiddleware.js
```javascript
const fs = require('fs');
const path = require('path');
const { v4: uuidv4 } = require('uuid');

// Configuration
const CHUNK_SIZE = 5 * 1024 * 1024; // 5MB chunks
const UPLOAD_DIR = path.join(__dirname, '..', '..', 'file');
const CHUNK_DIR = path.join(UPLOAD_DIR, 'chunks');

// Create directories if they don't exist
function ensureDirectory(dir) {
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
}

// Initialize chunk directory
ensureDirectory(CHUNK_DIR);

// Generate unique upload ID for each file
function generateUploadId() {
  return uuidv4();
}

// Get file info from request
function getFileInfo(req) {
  const fileName = req.body.filename || req.files?.[0]?.originalname || 'unknown';
  const uploadId = req.body.uploadId || generateUploadId();
  const totalChunks = req.body.totalChunks || 1;
  const chunkNumber = req.body.chunkNumber || 1;

  return {
    fileName,
    uploadId,
    totalChunks,
    chunkNumber
  };
}

// Handle chunk upload
async function uploadChunk(req, res) {
  try {
    // Ensure upload directory exists
    ensureDirectory(UPLOAD_DIR);

    // Get file info
    const fileInfo = getFileInfo(req);
    const { fileName, uploadId, totalChunks, chunkNumber } = fileInfo;

    // Create chunk path
    const chunkPath = path.join(CHUNK_DIR, `${uploadId}-${chunkNumber}`);

    // Read file data
    const fileData = req.body.fileData || req.body.file || req.files?.[0]?.buffer;

    if (!fileData) {
      return res.status(400).json({ error: 'No file data provided' });
    }

    // Write chunk to file
    fs.writeFileSync(chunkPath, fileData);

    // Create metadata file
    const metadataPath = path.join(CHUNK_DIR, `${uploadId}.metadata`);
    const metadata = {
      fileName,
      uploadId,
      totalChunks,
      chunkNumber,
      chunks: [],
      completed: false
    };

    // Read existing metadata if it exists
    let existingMetadata = {};
    if (fs.existsSync(metadataPath)) {
      existingMetadata = JSON.parse(fs.readFileSync(metadataPath, 'utf-8'));
    }

    // Update metadata with current chunk
    existingMetadata[chunks] = existingMetadata[chunks] || [];
    existingMetadata[chunks].push(chunkNumber);

    // Write updated metadata
    fs.writeFileSync(metadataPath, JSON.stringify(existingMetadata, null, 2));

    // Return success response
    res.status(200).json({
      success: true,
      message: `Chunk ${chunkNumber} uploaded successfully`,
      uploadId,
      chunkNumber,
      totalChunks
    });
  } catch (error) {
    console.error('Error uploading chunk:', error);
    res.status(500).json({ error: 'Failed to upload chunk' });
  }
}

// Get chunk information
function getChunkInfo(req, res) {
  try {
    const { uploadId } = req.query;
    if (!uploadId) {
      return res.status(400).json({ error: 'uploadId is required' });
    }

    const metadataPath = path.join(CHUNK_DIR, `${uploadId}.metadata`);

    if (!fs.existsSync(metadataPath)) {
      return res.status(404).json({ error: 'Upload not found' });
    }

    const metadata = JSON.parse(fs.readFileSync(metadataPath, 'utf-8'));

    res.status(200).json({
      uploadId,
      fileName: metadata.fileName,
      totalChunks: metadata.totalChunks,
      completedChunks: metadata.chunks.length,
      completed: metadata.chunks.length >= metadata.totalChunks
    });
  } catch (error) {
    console.error('Error getting chunk info:', error);
    res.status(500).json({ error: 'Failed to get chunk info' });
  }
}

// Get upload status
function getUploadStatus(req, res) {
  try {
    const { uploadId } = req.query;
    if (!uploadId) {
      return res.status(400).json({ error: 'uploadId is required' });
    }

    const metadataPath = path.join(CHUNK_DIR, `${uploadId}.metadata`);

    if (!fs.existsSync(metadataPath)) {
      return res.status(404).json({ error: 'Upload not found' });
    }

    const metadata = JSON.parse(fs.readFileSync(metadataPath, 'utf-8'));

    // Check if all chunks are uploaded
    const isComplete = metadata.chunks.length >= metadata.totalChunks;

    // If complete, combine chunks into final file
    if (isComplete) {
      const finalFilePath = path.join(UPLOAD_DIR, `${metadata.fileName}`);

      // Read all chunks
      const chunks = [];
      for (let i = 1; i <= metadata.totalChunks; i++) {
        const chunkPath = path.join(CHUNK_DIR, `${uploadId}-${i}`);
        if (fs.existsSync(chunkPath)) {
          chunks.push(fs.readFileSync(chunkPath));
        }
      }

      // Combine chunks
      const combinedData = Buffer.concat(chunks);

      // Write final file
      fs.writeFileSync(finalFilePath, combinedData);

      // Clean up chunks
      for (let i = 1; i <= metadata.totalChunks; i++) {
        const chunkPath = path.join(CHUNK_DIR, `${uploadId}-${i}`);
        if (fs.existsSync(chunkPath)) {
          fs.unlinkSync(chunkPath);
        }
      }

      // Update metadata
      metadata.completed = true;
      fs.writeFileSync(metadataPath, JSON.stringify(metadata, null, 2));
    }

    res.status(200).json({
      uploadId,
      fileName: metadata.fileName,
      totalChunks: metadata.totalChunks,
      completedChunks: metadata.chunks.length,
      completed: isComplete,
      finalFilePath: isComplete ? path.join(UPLOAD_DIR, metadata.fileName) : null
    });
  } catch (error) {
    console.error('Error getting upload status:', error);
    res.status(500).json({ error: 'Failed to get upload status' });
  }
}

module.exports = {
  uploadChunk,
  getChunkInfo,
  getUploadStatus
};
```

